def _ctx() -> MagicMock:
    ctx = MagicMock()
    ctx.taxonomy = sentinel.taxonomy
    ctx.issuer_sector_resolver = sentinel.resolver
    ctx.contribution_sector_resolver = sentinel.contribution_resolver
