def test_command_json_artifact_writer_does_not_write_directly_to_final_path(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    output = tmp_path / "artifact.json"
    original_write_bytes = Path.write_bytes

    def guarded_write_bytes(path: Path, data: bytes) -> int:
        if path == output:
            raise AssertionError("direct final-path write")
        return original_write_bytes(path, data)

    monkeypatch.setattr(Path, "write_bytes", guarded_write_bytes)

    digest = _write_json_artifact(output, {"ok": True})

    assert json.loads(output.read_text(encoding="utf-8")) == {"ok": True}
    assert digest == hashlib.sha256(output.read_bytes()).hexdigest()


def test_dispatch_runtime_env_preflight_reports_presence_without_secret_values(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("OPENAI_API_KEY", "sk-secret-value")
    monkeypatch.delenv("OPENPACT_POSTGRES_DSN", raising=False)
    dotenv = tmp_path / ".env"
    dotenv.write_text(
        "OPENAI_API_KEY=sk-dotenv-secret\nOPENPACT_POSTGRES_DSN=postgresql://secret\n",
        encoding="utf-8",
    )
    output = tmp_path / "env-preflight.json"
    template_output = tmp_path / "openpact.env.example"
    guarded_outputs = {output, template_output}
    seen_temp_targets: set[str] = set()
    original_open = Path.open

    def guarded_open(path: Path, *args: object, **kwargs: object):
        mode = str(args[0]) if args else str(kwargs.get("mode", "r"))
        if path in guarded_outputs and any(flag in mode for flag in ("w", "a", "x", "+")):
            raise AssertionError(f"direct final-path write: {path.name}")
        for final_path in guarded_outputs:
            prefix = f".{final_path.name}."
            if (
                path.parent == final_path.parent
                and path.name.startswith(prefix)
                and path.name.endswith(".tmp")
            ):
                UUID(path.name.removeprefix(prefix).removesuffix(".tmp"))
                seen_temp_targets.add(final_path.name)
        return original_open(path, *args, **kwargs)

    monkeypatch.setattr(Path, "open", guarded_open)

    result = dispatch_command(
        SimpleNamespace(
            command="runtime-env-preflight",
            require_env=["OPENAI_API_KEY", "OPENPACT_POSTGRES_DSN"],
            dotenv=str(dotenv),
            output=str(output),
            template_output=str(template_output),
        )
    )

    written = json.loads(output.read_text(encoding="utf-8"))
    template = template_output.read_text(encoding="utf-8")
    assert result["ok"] is False
    assert result["missing_env"] == ["OPENPACT_POSTGRES_DSN"]
    assert result["dotenv"]["dotenv_only"] == ["OPENPACT_POSTGRES_DSN"]
    assert result["next_actions"] == [f"source_dotenv:{dotenv}"]
    assert result["next_actions_by_env"] == {"OPENPACT_POSTGRES_DSN": [f"source_dotenv:{dotenv}"]}
    assert result["checks"] == [
        {
            "name": "OPENAI_API_KEY",
            "visible_to_process": True,
            "present_in_dotenv": True,
            "source": "process",
        },
        {
            "name": "OPENPACT_POSTGRES_DSN",
            "visible_to_process": False,
            "present_in_dotenv": True,
            "source": "dotenv_only",
        },
    ]
    serialized = json.dumps(result, sort_keys=True)
    assert "sk-secret-value" not in serialized
    assert "sk-dotenv-secret" not in serialized
    assert "postgresql://secret" not in serialized
    assert template == (
        "# OpenPact runtime environment template.\n"
        "# Fill values locally; do not commit secrets.\n"
        "OPENAI_API_KEY=\n"
        "OPENPACT_POSTGRES_DSN=\n"
    )
    assert result["template_output"] == str(template_output)
    assert (
        result["template_output_sha256"] == hashlib.sha256(template_output.read_bytes()).hexdigest()
    )
    assert written["run_metadata"] == result["run_metadata"]
    assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
    assert seen_temp_targets == {path.name for path in guarded_outputs}


def test_dispatch_runtime_env_preflight_reports_set_actions_for_absent_env(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.delenv("OPENAI_API_KEY", raising=False)
    dotenv = tmp_path / "missing.env"

    result = dispatch_command(
        SimpleNamespace(
            command="runtime-env-preflight",
            require_env=["OPENAI_API_KEY"],
            dotenv=str(dotenv),
            output=None,
            template_output=str(tmp_path / "openpact.env.example"),
        )
    )

    assert result["ok"] is False
    assert result["missing_env"] == ["OPENAI_API_KEY"]
    assert result["issues"] == [f"dotenv file not found: {dotenv}"]
    assert result["next_actions"] == [
        f"create_dotenv_from_template:{dotenv}:{tmp_path / 'openpact.env.example'}",
        "set_env:OPENAI_API_KEY",
    ]
    assert result["next_actions_by_env"] == {"OPENAI_API_KEY": ["set_env:OPENAI_API_KEY"]}
    assert result["dotenv"]["create_from_template_action"] == (
        f"create_dotenv_from_template:{dotenv}:{tmp_path / 'openpact.env.example'}"
    )


def test_dispatch_verify_runtime_env_preflight_accepts_sanitized_artifact(
    tmp_path: Path,
) -> None:
    template = tmp_path / "openpact.env.example"
    template.write_text(
        "# OpenPact runtime environment template.\n"
        "# Fill values locally; do not commit secrets.\n"
        "OPENAI_API_KEY=\n",
        encoding="utf-8",
    )
    artifact = tmp_path / "env-preflight.json"
    artifact.write_text(
        json.dumps(
            {
                "command": "runtime-env-preflight",
                "ok": False,
                "checked": 1,
                "checks": [
                    {
                        "name": "OPENAI_API_KEY",
                        "visible_to_process": False,
                        "present_in_dotenv": False,
                        "source": "absent",
                    }
                ],
                "missing_env": ["OPENAI_API_KEY"],
                "missing_env_count": 1,
                "next_actions": [
                    "set_env:OPENAI_API_KEY",
                    f"create_dotenv_from_template:{tmp_path / '.env'}:{template}",
                ],
                "next_actions_by_env": {"OPENAI_API_KEY": ["set_env:OPENAI_API_KEY"]},
                "dotenv": {
                    "path": str(tmp_path / ".env"),
                    "exists": False,
                    "dotenv_only": [],
                    "dotenv_only_count": 0,
                    "create_from_template_action": (
                        f"create_dotenv_from_template:{tmp_path / '.env'}:{template}"
                    ),
                },
                "issues": [f"dotenv file not found: {tmp_path / '.env'}"],
                "issue_count": 1,
                "template_output": str(template),
                "template_output_sha256": hashlib.sha256(template.read_bytes()).hexdigest(),
                "run_metadata": {"command": "runtime-env-preflight"},
            },
            sort_keys=True,
        ),
        encoding="utf-8",
    )
    output = tmp_path / "env-preflight-verify.json"

    result = dispatch_command(
        SimpleNamespace(
            command="verify-runtime-env-preflight",
            artifact=str(artifact),
            require_next_actions=True,
            require_template_output=True,
            require_no_secret_literals=True,
            output=str(output),
        )
    )
    written = json.loads(output.read_text(encoding="utf-8"))

    assert result["ok"] is True
    assert result["issue_count"] == 0
    assert result["quality_gate_failure_count"] == 0
    assert result["artifact_sha256"] == hashlib.sha256(artifact.read_bytes()).hexdigest()
    assert result["template_output_sha256"] == hashlib.sha256(template.read_bytes()).hexdigest()
    assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
    assert written["run_metadata"]["source_state"] == {
        "checked": 1,
        "missing_env_count": 1,
        "next_action_count": 2,
        "template_output_present": True,
        "template_output_sha256_invalid": False,
        "secret_literal_count": 0,
    }


def test_dispatch_verify_runtime_env_preflight_rejects_weak_or_secret_artifact(
    tmp_path: Path,
) -> None:
    artifact = tmp_path / "env-preflight.json"
    artifact.write_text(
        json.dumps(
            {
                "command": "runtime-env-preflight",
                "checked": 1,
                "checks": [],
                "missing_env": ["OPENAI_API_KEY"],
                "missing_env_count": 0,
                "next_actions": [],
                "dotenv": {"dotenv_only": ["OPENAI_API_KEY"], "dotenv_only_count": 0},
                "issues": ["sk-secret-value"],
                "issue_count": 0,
            },
            sort_keys=True,
        ),
        encoding="utf-8",
    )

    result = dispatch_command(
        SimpleNamespace(
            command="verify-runtime-env-preflight",
            artifact=str(artifact),
            require_next_actions=True,
            require_template_output=True,
            require_no_secret_literals=True,
            output=None,
        )
    )

    assert result["ok"] is False
    assert "checked_count_mismatch" in result["issues"]
    assert "missing_env_count_mismatch" in result["issues"]
    assert "dotenv_only_count_mismatch" in result["issues"]
    assert "issue_count_mismatch" in result["issues"]
    assert "missing_next_actions" in result["quality_gate_failures"]
    assert "template_output_missing" in result["quality_gate_failures"]
    assert "secret_literal:openai_token" in result["quality_gate_failures"]


