def _history_backfill_result_for_command(report_path: Path) -> LocalHistoryBackfillResult:
    plan = HistoryBackfillPlan(
        congress=119,
        date_window=CongressDateWindow(
            congress=119,
            start_date=dt.date(2025, 1, 3),
            end_date=dt.date(2025, 1, 6),
            bounded_by_today=True,
        ),
        cadence="weekly:monday",
        targets=[
            HistoricalSnapshotTarget(
                congress=119,
                snapshot_date=dt.date(2025, 1, 6),
                snapshot_id="2025-01-06",
                publish_root=report_path.parent.parent / "2025-01-06",
            )
        ],
    )
    execution = HistoryBackfillExecutionResult(
        plan=plan,
        attempts=[
            HistoryBackfillAttempt(
                snapshot_id="2025-01-06",
                snapshot_date=dt.date(2025, 1, 6),
                publish_root=report_path.parent.parent / "2025-01-06",
                status="completed",
            )
        ],
    )
    return LocalHistoryBackfillResult(
        execution=execution,
        snapshot_results={},
        aggregate_source_roots=[report_path.parent.parent / "2025-01-06"],
        target_root=report_path.parent.parent,
        overwrite=False,
        continue_on_error=False,
        report_path=report_path,
    )


@contextmanager
def _command_env():
    """Patch open_connection and yield ctx + conn for command-level tests."""
    ctx = _ctx()
    conn = MagicMock()
    with patch(f"{_MODULE}.open_connection", return_value=conn) as mock_open:
        yield SimpleNamespace(ctx=ctx, conn=conn, mock_open=mock_open)


class TestOracleSummaryOk:
    def test_returns_false_when_congress_stage_fails(self) -> None:
        summary = {
            "congress": {"load_ok": False},
            "disclosures": {"load_ok": True},
            "publish": {"succeeded": True},
            "verify": {"ok": True},
            "roundtrip": {"ok": True},
        }

        assert _oracle_summary_ok(summary) is False

    def test_returns_false_when_disclosures_stage_fails(self) -> None:
        summary = {
            "congress": {"load_ok": True},
            "disclosures": {"load_ok": False},
            "publish": {"succeeded": True},
            "verify": {"ok": True},
            "roundtrip": {"ok": True},
        }

        assert _oracle_summary_ok(summary) is False


