class TestVerifyPublicStatementRows:
    def test_dispatch_passes_source_backed_statement_rows(self, tmp_path: Path) -> None:
        statement_rows = tmp_path / "statements.jsonl"
        output = tmp_path / "statement-verify.json"
        statement_rows.write_text(
            "\n".join(
                [
                    json.dumps(
                        {
                            "member_bioguide_id": "A000001",
                            "statement_id": "stmt-001",
                            "statement_date": "2024-05-02",
                            "sector": "energy",
                            "statement_source_url": "https://a.house.gov/news/energy",
                        }
                    ),
                    json.dumps(
                        {
                            "member_bioguide_id": "B000002",
                            "source_record_id": "stmt-002",
                            "statement_date": "2024-06-03",
                            "sector": "defense",
                            "statement_source_url": "https://b.senate.gov/news/defense",
                        }
                    ),
                ]
            )
            + "\n",
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-public-statement-rows",
                statement_rows=str(statement_rows),
                min_rows=2,
                output=str(output),
            )
        )

        written = json.loads(output.read_text(encoding="utf-8"))
        assert result["ok"] is True, result["issues"]
        assert result["issue_count"] == 0
        assert result["quality_gate_failure_count"] == 0
        assert result["row_count"] == 2
        assert result["member_count"] == 2
        assert result["sector_count"] == 2
        assert result["official_source_url_count"] == 2
        assert result["date_range"] == {"min": "2024-05-02", "max": "2024-06-03"}
        assert result["artifact_sha256"] == hashlib.sha256(statement_rows.read_bytes()).hexdigest()
        assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
        assert written["command"] == "verify-public-statement-rows"
        assert written["run_metadata"] == {
            "command": "verify-public-statement-rows",
            "artifact_sha256": hashlib.sha256(statement_rows.read_bytes()).hexdigest(),
            "verification_flags": {"min_rows": 2},
            "source_state": {
                "row_count": 2,
                "member_count": 2,
                "sector_count": 2,
                "official_source_url_count": 2,
                "duplicate_source_id_count": 0,
                "date_range": {"min": "2024-05-02", "max": "2024-06-03"},
            },
        }

