class TestMaterializePublicStatementRows:
    def test_dispatch_materializes_statement_rows(self, tmp_path: Path) -> None:
        raw = tmp_path / "raw-statements.jsonl"
        output = tmp_path / "prepared-statements.jsonl"
        taxonomy = tmp_path / "sectors.yaml"
        summary = tmp_path / "statement-materialize.json"
        taxonomy.write_text(
            """
version: 1
sectors:
  - sector_id: energy_utilities
    label: Energy and Utilities
    aliases:
      - energy
""",
            encoding="utf-8",
        )
        raw.write_text(
            json.dumps(
                {
                    "member_bioguide_id": "A000001",
                    "statement_id": "stmt-001",
                    "statement_date": "2024-05-02",
                    "sector": "energy",
                    "statement_source_url": "https://a.house.gov/news/energy",
                }
            )
            + "\n",
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="materialize-public-statement-rows",
                input=str(raw),
                output=str(output),
                taxonomy=str(taxonomy),
                dry_run=False,
                force=False,
                summary_output=str(summary),
            )
        )

        prepared = [json.loads(line) for line in output.read_text(encoding="utf-8").splitlines()]
        written = json.loads(summary.read_text(encoding="utf-8"))
        assert result["ok"] is True
        assert result["row_count"] == 1
        assert result["sector_count"] == 1
        assert result["member_count"] == 1
        assert result["input_sha256"] == hashlib.sha256(raw.read_bytes()).hexdigest()
        assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
        assert result["summary_output_sha256"] == hashlib.sha256(summary.read_bytes()).hexdigest()
        assert prepared[0]["sector"] == "energy_utilities"
        assert written["command"] == "materialize-public-statement-rows"
        assert written["run_metadata"] == {
            "command": "materialize-public-statement-rows",
            "source_state": {
                "dry_run": False,
                "force": False,
                "row_count": 1,
                "skipped_count": 0,
                "member_count": 1,
                "sector_count": 1,
                "input_path": str(raw),
                "output_path": str(output),
            },
            "artifact_sha256": {
                "input_sha256": hashlib.sha256(raw.read_bytes()).hexdigest(),
                "output_sha256": hashlib.sha256(output.read_bytes()).hexdigest(),
            },
        }

