        output = tmp_path / "fec-inputs-verify.json"
        committee.write_text("C00000001|Committee\n", encoding="latin-1")
        linkage.write_text("H4MI00001|2024|2024|C00000001|H|P|123\n", encoding="latin-1")
        contributions.write_text("C00000001|N|Q1|P|IMG|10\n", encoding="latin-1")
