    def test_dispatch_rejects_invalid_date_windows_before_writing(
        self,
        tmp_path: Path,
    ) -> None:
        output = tmp_path / "inventory.json"

        with (
            patch(f"{_PREDICTION_INPUT_INVENTORY_MODULE}.build_runtime") as build_runtime,
            patch(
                f"{_PREDICTION_INPUT_INVENTORY_MODULE}.run_prediction_input_inventory_command"
            ) as run_inventory,
        ):
            result = dispatch_command(
                SimpleNamespace(
                    command="prediction-input-inventory",
                    training_feature_cutoff=dt.date(2023, 1, 1),
                    train_start=dt.date(2023, 1, 1),
                    train_end=dt.date(2022, 12, 31),
                    feature_cutoff=dt.date(2025, 1, 1),
                    label_start=dt.date(2025, 1, 1),
                    label_end=dt.date(2024, 12, 31),
                    output=str(output),
                )
            )

        assert result == {
            "ok": False,
            "command": "prediction-input-inventory",
            "issues": [
                "train_start must be on or before train_end",
                "label_start must be on or before label_end",
                "training_feature_cutoff must be before train_start",
                "feature_cutoff must be before label_start",
            ],
            "issue_count": 4,
        }
        build_runtime.assert_not_called()
        run_inventory.assert_not_called()
        assert not output.exists()

