    def test_dispatch_verify_prediction_input_inventory_rejects_malformed_artifact(
        self,
        tmp_path: Path,
    ) -> None:
        artifact = tmp_path / "inventory.json"
        artifact.write_text("{}", encoding="utf-8")
        output = tmp_path / "inventory-verify.json"

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-input-inventory",
                artifact=str(artifact),
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is False
        assert result["output"] == str(output)
        assert written["ok"] is False
        assert (
            written["run_metadata"]["artifact_sha256"]
            == hashlib.sha256(artifact.read_bytes()).hexdigest()
        )
        assert result["checked"] == 0
        assert any("artifact schema:" in issue for issue in result["issues"])


