    def test_dispatch_materialize_bill_semantics_delegates_to_openai_extractor(
        self, tmp_path: Path
    ) -> None:
        index_path = tmp_path / "index.json"
        index_path.write_text('{"bill_count": 0, "bills": []}', encoding="utf-8")
        materialized = SimpleNamespace(
            output_root=tmp_path,
            requested_count=2,
            written_count=1,
            cached_count=1,
            index_path=index_path,
        )
        summary_output = tmp_path / "bill-semantics-summary.json"
        with (
            patch(f"{_MODULE}.build_runtime", return_value=SimpleNamespace(context=sentinel.ctx)),
            patch(f"{_MODULE}.open_connection", return_value=sentinel.conn),
            patch(f"{_MODULE}.fetch_bill_semantic_input_rows", return_value=[{"bill": 1}]) as rows,
            patch(
                f"{_MODULE}.OpenAIBillSemanticExtractor.from_env", return_value=sentinel.extractor
            ),
            patch(
                f"{_MODULE}.materialize_bill_semantics", return_value=materialized
            ) as mock_materialize,
        ):
            result = dispatch_command(
                SimpleNamespace(
                    command="materialize-bill-semantics",
                    output_root=str(tmp_path),
                    model="gpt-5.5",
                    feature_cutoff=dt.date(2024, 12, 31),
                    limit=2,
                    overwrite=True,
                    summary_output=str(summary_output),
                )
            )

        mock_materialize.assert_called_once_with(
            bill_rows=[{"bill": 1}],
            output_root=tmp_path,
            extractor=sentinel.extractor,
            limit=2,
            overwrite=True,
        )
        rows.assert_called_once_with(sentinel.conn, feature_cutoff=dt.date(2024, 12, 31))
        assert result["command"] == "materialize-bill-semantics"
        assert result["model"] == "gpt-5.5"
        assert result["summary_output"] == str(summary_output)
        assert (
            result["summary_output_sha256"]
            == hashlib.sha256(summary_output.read_bytes()).hexdigest()
        )
        summary = json.loads(summary_output.read_text(encoding="utf-8"))
        assert summary["run_metadata"] == {
            "command": "materialize-bill-semantics",
            "dry_run": False,
            "model": "gpt-5.5",
            "output_root": str(tmp_path),
            "feature_cutoff": "2024-12-31",
            "limit": 2,
            "overwrite": True,
            "fail_on_unmatched_targets": False,
            "target_bill_keys": [],
            "matched_bill_keys": [],
            "unmatched_bill_keys": [],
            "index_sha256": hashlib.sha256(index_path.read_bytes()).hexdigest(),
            "source_state": {
                "dry_run": False,
                "model": "gpt-5.5",
                "output_root": str(tmp_path),
                "feature_cutoff": "2024-12-31",
                "requested_count": 2,
                "written_count": 1,
                "cached_count": 1,
                "target_bill_count": 0,
                "matched_bill_count": 0,
                "unmatched_bill_count": 0,
                "index_path": str(index_path),
                "index_sha256": hashlib.sha256(index_path.read_bytes()).hexdigest(),
            },
        }
        assert result["written_count"] == 1
        assert result["index_path"] == str(index_path)
        assert result["index_sha256"] == hashlib.sha256(index_path.read_bytes()).hexdigest()

