    def test_dispatch_verify_bill_semantics_reports_cache_error(self, tmp_path: Path) -> None:
        (tmp_path / "index.json").write_text(
            json.dumps(
                {
                    "bill_count": 1,
                    "bills": [
                        {
                            "bill_key": "119-hr-1",
                            "path": "bills/missing.json",
                            "sha256": "0" * 64,
                            "available_at": None,
                            "sector_ids": [],
                            "source_anchor_count": 1,
                        }
                    ],
                }
            ),
            encoding="utf-8",
        )

        output = tmp_path / "bill-semantics-verify.json"
        result = dispatch_command(
            SimpleNamespace(
                command="verify-bill-semantics",
                root=str(tmp_path),
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is False
        assert written["ok"] is False
        assert (
            written["run_metadata"]["index_sha256"]
            == hashlib.sha256((tmp_path / "index.json").read_bytes()).hexdigest()
        )
        assert written["run_metadata"]["source_state"] == {
            "root": str(tmp_path),
            "index_path": str(tmp_path / "index.json"),
            "index_sha256": hashlib.sha256((tmp_path / "index.json").read_bytes()).hexdigest(),
            "bill_count": 0,
            "bill_keys": [],
            "model_names": [],
            "source_bill_count": None,
            "source_bill_keys": [],
            "source_inputs_sha256": None,
            "unofficial_source_anchor_count": None,
        }
        assert result["bill_count"] == 0
        assert result["issues"]
        assert result["issue_count"] == len(result["issues"])
        assert result["quality_gate_failures"] == []
        assert result["quality_gate_failure_count"] == 0

    def test_dispatch_verify_bill_semantics_plan_passes_valid_plan(
        self,
        tmp_path: Path,
    ) -> None:
        report = tmp_path / "prediction-eval-report.json"
        report.write_text('{"report": true}', encoding="utf-8")
        plan = tmp_path / "bill-semantics-plan.json"
        plan.write_text(
            json.dumps(
                {
                    "command": "materialize-bill-semantics",
                    "dry_run": True,
                    "feature_cutoff": "2024-12-31",
                    "inputs": {
                        "bill_keys": [],
                        "missing_from_report": str(report),
                        "missing_from_report_sha256": hashlib.sha256(
                            report.read_bytes()
                        ).hexdigest(),
                    },
                    "target_bill_keys": ["119-hr-1"],
                    "matched_bill_keys": ["119-hr-1"],
                    "unmatched_bill_keys": [],
                    "requested_count": 1,
                    "matched_bills": [
                        {
                            "bill_key": "119-hr-1",
                            "title": "Matched bill",
                            "summary": "",
                            "available_at": "2024-12-01",
                            "source_anchors": [
                                {
                                    "source_type": "congress_bill",
                                    "source_id": "119-hr-1",
                                    "url": "https://api.congress.gov/v3/bill/119/hr/1",
                                    "label": "Congress.gov bill 119-hr-1",
                                }
                            ],
                            "source_anchor_count": 1,
                        }
                    ],
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )

        output = tmp_path / "bill-semantics-plan-verify.json"
        result = dispatch_command(
            SimpleNamespace(
                command="verify-bill-semantics-plan",
                plan=str(plan),
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is True
        assert result["output"] == str(output)
        assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
        assert written["run_metadata"] == {
            "command": "verify-bill-semantics-plan",
            "verification_flags": {
                "fail_on_unmatched_targets": False,
                "require_source_report": False,
                "require_matched_source_anchors": False,
            },
            "artifact_sha256": hashlib.sha256(plan.read_bytes()).hexdigest(),
            "source_state": {
                "feature_cutoff": "2024-12-31",
                "target_bill_count": 1,
                "matched_bill_count": 1,
                "unmatched_bill_count": 0,
                "target_bill_keys": ["119-hr-1"],
                "matched_bill_keys": ["119-hr-1"],
                "unmatched_bill_keys": [],
                "matched_source_anchor_count": 1,
                "matched_bill_source_anchor_count": 1,
                "requested_count": 1,
                "missing_from_report": str(report),
                "missing_from_report_sha256": hashlib.sha256(report.read_bytes()).hexdigest(),
            },
        }
        assert result["checked"] == 2
        assert result["issues"] == []
        assert result["issue_count"] == 0
        assert result["quality_gate_failures"] == []
        assert result["quality_gate_failure_count"] == 0
        assert result["matched_bill_count"] == 1

