    def test_dispatch_prediction_backtest_warns_and_can_fail_without_ontology_semantics(
        self,
        tmp_path: Path,
    ) -> None:
        payload = build_vote_baseline_backtest(
            feature_cutoff=dt.date(2024, 12, 31),
            label_start=dt.date(2025, 1, 1),
            label_end=dt.date(2025, 12, 31),
            feature_rows=[],
            label_rows=[],
        )
        output = tmp_path / "prediction-backtest.json"
        with (
            patch(
                f"{_PREDICTION_BACKTEST_MODULE}.build_runtime",
                return_value=SimpleNamespace(context=sentinel.ctx),
            ),
            patch(
                f"{_PREDICTION_BACKTEST_MODULE}.run_prediction_backtest_command",
                return_value=payload,
            ),
        ):
            result = dispatch_command(
                SimpleNamespace(
                    command="prediction-backtest",
                    feature_cutoff=dt.date(2024, 12, 31),
                    label_start=dt.date(2025, 1, 1),
                    label_end=dt.date(2025, 12, 31),
                    model="ontology",
                    bill_semantics_root=None,
                    fail_on_mixed_bill_semantics_models=False,
                    fail_on_missing_bill_semantics_root=True,
                    output=str(output),
                )
            )

        assert result["ok"] is False
        assert result["warning_reasons"] == ["missing_bill_semantics_root"]
        assert result["quality_gate_failures"] == ["missing_bill_semantics_root"]
        written = json.loads(output.read_text(encoding="utf-8"))
        assert written["run_metadata"]["bill_semantics_root"] is None
        assert written["run_metadata"]["warning_reasons"] == ["missing_bill_semantics_root"]
        assert written["run_metadata"]["source_state"]["warning_reason_count"] == 1
        assert written["run_metadata"]["source_state"]["warning_reasons"] == [
            "missing_bill_semantics_root"
        ]

