    def test_dispatch_verify_prediction_backtest_rejects_malformed_bill_semantics_metadata(
        self,
        tmp_path: Path,
    ) -> None:
        payload = build_vote_baseline_backtest(
            feature_cutoff=dt.date(2024, 12, 31),
            label_start=dt.date(2025, 1, 1),
            label_end=dt.date(2025, 12, 31),
            feature_rows=[],
            label_rows=[],
        ).model_dump(mode="json")
        payload["run_metadata"] = {
            "bill_semantics_root": " /tmp/bill-semantics ",
            "bill_semantics_index_sha256": "not-a-sha",
            "bill_semantics_model_names": ["gpt-5.5", "gpt-5.5", " gpt-5.4-mini", ""],
        }
        artifact = tmp_path / "prediction-backtest.json"
        artifact.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")

        result = dispatch_command(
            SimpleNamespace(command="verify-prediction-backtest", artifact=str(artifact))
        )

        assert result["ok"] is False
        assert "bill-semantics index: root must be trimmed" in result["issues"]
        assert "bill-semantics index: invalid sha256" in result["issues"]
        assert "bill-semantics index: model_names must be non-empty" in result["issues"]
        assert "bill-semantics index: model_names must be trimmed" in result["issues"]
        assert "bill-semantics index: model_names must be unique" in result["issues"]

    def test_dispatch_verify_prediction_backtest_rejects_malformed_artifact(
        self,
        tmp_path: Path,
    ) -> None:
        artifact = tmp_path / "prediction-backtest.json"
        artifact.write_text("{}", encoding="utf-8")
        output = tmp_path / "backtest-verify.json"

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-backtest",
                artifact=str(artifact),
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is False
        assert result["output"] == str(output)
        assert written["ok"] is False
        assert (
            written["run_metadata"]["artifact_sha256"]
            == hashlib.sha256(artifact.read_bytes()).hexdigest()
        )
        assert result["checked"] == 0
        assert any("artifact schema:" in issue for issue in result["issues"])


