    def test_dispatch_verify_prediction_benchmark_verifies_eval_window_run(
        self,
        tmp_path: Path,
    ) -> None:
        paths = self._write_valid_benchmark_bundle(tmp_path)
        eval_window_run_verify = _write_eval_window_run_verify_artifact(tmp_path)

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-benchmark",
                inventory=str(paths["inventory"]),
                backtest=str(paths["backtest"]),
                eval_manifest=str(paths["eval_manifest"]),
                bill_semantics_plan=str(paths["bill_semantics_plan"]),
                eval_window_run_verify=str(eval_window_run_verify),
                require_eval_window_run_verify=True,
                fail_on_unmatched_targets=False,
            )
        )

        assert result["ok"] is True
        assert result["component_count"] == 5
        assert result["components"]["eval_window_run"]["ok"] is True
        assert result["components"]["eval_window_run"]["current_result"]["ok"] is True
        assert (
            result["components"]["eval_window_run"]["current_result"]["run_metadata"][
                "source_state"
            ]["requires_training_labels"]
            is True
        )
        assert (
            result["components"]["eval_window_run"]["current_result"]["run_metadata"][
                "source_state"
            ]["requires_evaluation_labels"]
            is True
        )
        source_state = result["components"]["eval_window_run"]["current_result"]["run_metadata"][
            "source_state"
        ]
        assert source_state["requires_input_inventory_portable_ids"] is True
        assert source_state["requires_input_inventory_congress_source_families"] is True
        assert source_state["requires_input_inventory_official_source_thresholds"] is True
        assert source_state["requires_input_inventory_optional_evidence"] is True
        assert source_state["requires_eval_manifest_model_suite"] is True
        assert source_state["requires_eval_manifest_official_source_thresholds"] is True
        assert source_state["requires_eval_manifest_unknown_availability_failures"] is True
        assert source_state["requires_eval_manifest_ontology_feature_signals"] is True
        component_source_state = result["components"]["eval_window_run"]["run_metadata"][
            "source_state"
        ]
        assert component_source_state["strict_eval_window_run_ready"] is True
        assert component_source_state["requires_input_inventory_portable_ids"] is True
        assert component_source_state["requires_eval_manifest_official_source_thresholds"] is True
        benchmark_source_state = result["run_metadata"]["source_state"]["component_source_states"][
            "eval_window_run"
        ]
        assert benchmark_source_state["strict_eval_window_run_ready"] is True
        assert (
            benchmark_source_state["requires_eval_manifest_unknown_availability_failures"] is True
        )
        assert result["artifacts"]["eval_window_run_verify"]["path"] == str(eval_window_run_verify)
        assert (
            result["run_metadata"]["verification_flags"]["require_eval_window_run_verify"] is True
        )
        assert result["run_metadata"]["artifact_sha256"]["eval_window_run_verify"] == (
            hashlib.sha256(eval_window_run_verify.read_bytes()).hexdigest()
        )

