    def test_dispatch_verify_prediction_benchmark_rejects_mismatched_congress_archive_manifest(
        self,
        tmp_path: Path,
    ) -> None:
        paths = self._write_valid_benchmark_bundle(tmp_path)
        congress_archive_manifest = tmp_path / "congress_119" / "manifest.json"
        congress_archive_manifest.parent.mkdir()
        congress_archive_manifest.write_text(
            json.dumps({"congress": 119}, sort_keys=True),
            encoding="utf-8",
        )
        other_manifest = tmp_path / "congress_118" / "manifest.json"
        other_manifest.parent.mkdir()
        other_manifest.write_text(
            json.dumps({"congress": 118}, sort_keys=True),
            encoding="utf-8",
        )
        self._attach_benchmark_archive_manifest(paths, congress_archive_manifest)
        backtest_payload = json.loads(paths["backtest"].read_text(encoding="utf-8"))
        backtest_payload["run_metadata"]["congress_archive_manifest"] = {
            "path": str(other_manifest),
            "sha256": hashlib.sha256(other_manifest.read_bytes()).hexdigest(),
        }
        paths["backtest"].write_text(
            json.dumps(backtest_payload, sort_keys=True),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-benchmark",
                inventory=str(paths["inventory"]),
                backtest=str(paths["backtest"]),
                eval_manifest=str(paths["eval_manifest"]),
                bill_semantics_plan=str(paths["bill_semantics_plan"]),
                fail_on_unmatched_targets=False,
                require_inventory_congress_archive_manifest=True,
                require_backtest_congress_archive_manifest=True,
                require_eval_congress_archive_manifest=True,
            )
        )

        assert result["ok"] is False
        assert (
            "benchmark congress archive manifest mismatch: backtest.sha256 != inventory.sha256"
            in result["issues"]
        )
        assert (
            "benchmark congress archive manifest mismatch: backtest.path != inventory.path"
            in result["issues"]
        )

