        assert {
            "action": "backfill_feature_source_urls",
            "artifact": str(paths["eval_manifest"]),
        } in [
            {
                "action": recommendation["action"],
                "artifact": recommendation.get("artifact"),
            }
            for recommendation in result["backfill_recommendations"]
        ]

