    def test_dispatch_verify_prediction_benchmark_embeds_backfill_recommendations(
        self,
        tmp_path: Path,
    ) -> None:
        paths = self._write_valid_benchmark_bundle(tmp_path)
        manifest_payload = json.loads(paths["eval_manifest"].read_text(encoding="utf-8"))
        report_path = Path(manifest_payload["artifacts"]["report"]["path"])
        report_payload = json.loads(report_path.read_text(encoding="utf-8"))
        recommendations = [
            {
                "action": "backfill_feature_source_urls",
                "priority_score": 18,
                "reason": "Feature signals need URL-backed source anchors.",
                "affected_case_count": 6,
                "missing_bill_keys": [],
                "unavailable_signal_counts": {},
                "sample_vote_event_ids": [101, 102],
                "sample_cases": [
                    {
                        "vote_event_id": 101,
                        "event_key": None,
                        "jurisdiction_id": None,
                        "legislative_body_id": None,
                        "legislative_session_id": None,
                        "bill_key": "119-hr-1",
                        "member_bioguide_id": "A000001",
                    }
                ],
            }
        ]
        report_payload["backfill_recommendations"] = recommendations
        report_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 1
        report_path.write_text(
            json.dumps(report_payload, sort_keys=True),
            encoding="utf-8",
        )
        dataset_path = Path(manifest_payload["artifacts"]["dataset"]["path"])
        dataset_payload = json.loads(dataset_path.read_text(encoding="utf-8"))
        dataset_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 1
        dataset_path.write_text(
            json.dumps(dataset_payload, sort_keys=True),
            encoding="utf-8",
        )
        report_sha256 = hashlib.sha256(report_path.read_bytes()).hexdigest()
        dataset_sha256 = hashlib.sha256(dataset_path.read_bytes()).hexdigest()
        manifest_payload["artifacts"]["report"]["sha256"] = report_sha256
        manifest_payload["artifacts"]["dataset"]["sha256"] = dataset_sha256
        manifest_payload["source_state"]["backfill_recommendation_count"] = 1
        manifest_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 1
        paths["eval_manifest"].write_text(
            json.dumps(manifest_payload, sort_keys=True),
            encoding="utf-8",
        )
        plan_payload = json.loads(paths["bill_semantics_plan"].read_text(encoding="utf-8"))
        plan_payload["inputs"]["missing_from_report_sha256"] = report_sha256
        plan_payload["inputs"]["missing_from_report_run_metadata"] = report_payload["run_metadata"]
        paths["bill_semantics_plan"].write_text(
            json.dumps(plan_payload, sort_keys=True),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-benchmark",
                inventory=str(paths["inventory"]),
                backtest=str(paths["backtest"]),
                eval_manifest=str(paths["eval_manifest"]),
                bill_semantics_plan=str(paths["bill_semantics_plan"]),
                fail_on_unmatched_targets=False,
            )
        )

        assert result["ok"] is True
        assert result["backfill_recommendation_count"] == 1
        assert result["backfill_recommendations"] == recommendations
        assert result["backfill_plan"]["step_count"] == 1
        assert result["backfill_plan"]["steps"][0]["action"] == ("backfill_feature_source_urls")
        assert result["backfill_plan"]["steps"][0]["sample_cases"] == [
            {
                "vote_event_id": 101,
                "event_key": None,
                "jurisdiction_id": None,
                "legislative_body_id": None,
                "legislative_session_id": None,
                "bill_key": "119-hr-1",
                "member_bioguide_id": "A000001",
            }
        ]
        assert result["backfill_plan"]["steps"][0]["source_requirements"] == [
            "Reload or repair feature-producing rows so every claim-bearing feature signal carries an official HTTPS source URL and every non-Congress sample has explicit legislative_body_id and legislative_session_id context."
        ]
        assert result["backfill_plan"]["steps"][0]["runtime_requirements"] == [
            "env:OPENPACT_POSTGRES_DSN"
        ]
        assert result["backfill_plan"]["steps"][0]["suggested_commands"] == [
            "python3 -m src.runtime.main prediction-source-url-audit "
            f"--eval-report {report_path} --fail-on-gaps "
            "--output out/prediction-source-url-audit.json",
            "python3 -m src.runtime.main verify-prediction-source-url-audit "
            "--artifact out/prediction-source-url-audit.json "
            "--require-run-metadata --require-no-gaps "
            "--require-no-official-source-gaps "
            "--output out/prediction-source-url-audit-verify.json",
        ]

