        report_path.write_text(
            json.dumps(report_payload, sort_keys=True),
            encoding="utf-8",
        )
        report_sha256 = hashlib.sha256(report_path.read_bytes()).hexdigest()
        dataset_path = Path(manifest_payload["artifacts"]["dataset"]["path"])
        dataset_payload = json.loads(dataset_path.read_text(encoding="utf-8"))
        dataset_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 3
        dataset_path.write_text(
            json.dumps(dataset_payload, sort_keys=True),
            encoding="utf-8",
        )
        manifest_payload["artifacts"]["report"]["sha256"] = report_sha256
        manifest_payload["artifacts"]["dataset"]["sha256"] = hashlib.sha256(
            dataset_path.read_bytes()
        ).hexdigest()
        manifest_payload["source_state"]["backfill_recommendation_count"] = 3
        manifest_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 3
        paths["eval_manifest"].write_text(
            json.dumps(manifest_payload, sort_keys=True),
            encoding="utf-8",
        )
        plan_payload = json.loads(paths["bill_semantics_plan"].read_text(encoding="utf-8"))
        plan_payload["inputs"]["missing_from_report_sha256"] = report_sha256
        plan_payload["inputs"]["missing_from_report_run_metadata"] = report_payload["run_metadata"]
        paths["bill_semantics_plan"].write_text(
            json.dumps(plan_payload, sort_keys=True),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-benchmark",
                inventory=str(paths["inventory"]),
                backtest=str(paths["backtest"]),
                eval_manifest=str(paths["eval_manifest"]),
                bill_semantics_plan=str(paths["bill_semantics_plan"]),
                fail_on_unmatched_targets=False,
            )
        )

        assert result["ok"] is True
        assert result["backfill_plan"]["step_count"] == 3
        metadata_step, semantic_step, statement_step = result["backfill_plan"]["steps"]
        assert metadata_step["suggested_commands"] == [
            "python3 -m src.runtime.main load-congress --congress 118"
        ]
        assert metadata_step["runtime_requirements"] == [
            "env:OPENPACT_POSTGRES_DSN",
            "env:OPENPACT_CONGRESS_API_KEY",
        ]
        assert semantic_step["blocked_by"] == ["load_missing_bill_metadata"]
        assert semantic_step["runtime_requirements"] == [
            "env:OPENPACT_POSTGRES_DSN",
            "env:OPENAI_API_KEY",
            f"file:{report_path}",
        ]
        assert semantic_step["source_requirements"] == [
            "Use cutoff-available bill metadata and official source anchors for every semantic payload.",
            "Non-Congress bill keys require a jurisdiction-specific bill metadata and semantic materialization adapter before the Congress.gov bill-semantics command can satisfy them.",
        ]
        assert semantic_step["suggested_commands"] == [
            "python3 -m src.runtime.main materialize-bill-semantics "
            f"--output-root out/bill-semantics --missing-from-report {report_path} "
            "--feature-cutoff 2024-12-31 "
            f"--model gpt-5.5 --dry-run --plan-output {paths['bill_semantics_plan']} "
            "--summary-output out/bill-semantics-materialize-summary.json",
            "python3 -m src.runtime.main verify-bill-semantics-plan "
            f"--plan {paths['bill_semantics_plan']} --require-source-report "
            "--require-matched-source-anchors "
            "--output out/bill-semantics-plan-verify.json",
            "python3 -m src.runtime.main materialize-bill-semantics "
            f"--output-root out/bill-semantics --missing-from-report {report_path} "
            "--feature-cutoff 2024-12-31 "
            "--model gpt-5.5 "
            "--summary-output out/bill-semantics-materialize-summary.json",
            "python3 -m src.runtime.main verify-bill-semantics "
            "--root out/bill-semantics --require-model-name gpt-5.5 "
            "--require-source-inputs-sha256 --output out/bill-semantics-verify.json",
        ]
        assert semantic_step["unsupported_target_bill_keys"] == ["state_ca:119-hr-9"]
        assert statement_step["runtime_requirements"] == [
            "env:OPENPACT_POSTGRES_DSN",
            "file:data/taxonomy/sectors.yaml",
        ]
        assert statement_step["suggested_commands"] == [
            "python3 -m src.runtime.main materialize-public-statement-rss "
            "--output data/raw/public-statements.jsonl "
            "--summary-output out/public-statement-rss-materialize-summary.json",
            "python3 -m src.runtime.main materialize-public-statement-rows "
            "--input data/raw/public-statements.jsonl "
            "--output data/prepared/public-statement-sector-rows.jsonl "
            "--summary-output out/public-statement-rows-materialize-summary.json",
            "python3 -m src.runtime.main verify-public-statement-rows "
            "--statement-rows data/prepared/public-statement-sector-rows.jsonl "
            "--min-rows 1 --output out/public-statement-rows-verify.json",
            "python3 -m src.runtime.main recompute "
            "--statement-rows data/prepared/public-statement-sector-rows.jsonl",
        ]

