        report_payload["run_metadata"]["source_state"]["backfill_recommendation_count"] = 1
        report_path.write_text(
            json.dumps(report_payload, sort_keys=True),
            encoding="utf-8",
        )
        dataset_path = Path(manifest_payload["artifacts"]["dataset"]["path"])
        dataset_payload = json.loads(dataset_path.read_text(encoding="utf-8"))
