        assert missing_result["ok"] is False
        assert missing_result["offline_input_ok"] is False
        assert missing_result["congress_load_required"] is True
        assert missing_result["blockers"] == ["local_input:congress_load_missing"]
        assert missing_result["blocker_summary"]["by_category"]["local_inputs"] == 1
        assert "load_congress_prediction_inputs" in missing_result["next_live_actions"]
