    def test_dispatch_verify_prediction_offline_readiness_summary_accepts_sanitized_artifact(
        self,
        tmp_path: Path,
    ) -> None:
        script = tmp_path / "prediction-resume.sh"
        script.write_text(
            "\n".join(
                [
                    "#!/usr/bin/env bash",
                    "set -euo pipefail",
                    "",
                    "# Generated by prediction-offline-readiness-summary.",
                    "# Fill required environment variables locally before running a phase.",
                    "# Commands are derived from the verified prediction backfill plan.",
                    "",
                    "# Phase 1",
                    "# Missing requirements: env:OPENAI_API_KEY",
                    "# Actions: materialize_missing_bill_semantics",
                    "# Source artifacts:",
                    f"#   - {tmp_path / 'prediction-eval-manifest-verify.json'}",
                    "# Additional reasons:",
                    "#   - Eval manifest and backtest both need feature source URLs.",
                    ': "${OPENAI_API_KEY:?Set OPENAI_API_KEY before phase 1}"',
                    "python3 -m src.runtime.main materialize-bill-semantics "
                    "--output-root out/bill-semantics",
                    "",
                ]
            ),
            encoding="utf-8",
        )
        blocker_summary = {
            "total": 1,
            "by_category": {
                "benchmark_quality_gates": 0,
                "benchmark_issues": 0,
                "runtime_quality_gates": 0,
                "runtime_requirements": 0,
                "local_inputs": 0,
                "source_artifacts": 0,
                "env_preflight": 1,
            },
            "by_benchmark_component": {},
        }
        env_consistency: dict[str, object] = {"checked": True, "mismatch": False}
        source_state = {
            "offline_input_ok": True,
            "live_ready": False,
            "blocker_count": 1,
            "blocker_summary": blocker_summary,
            "benchmark_component_count": 0,
            "benchmark_quality_gate_failure_count": 0,
            "missing_runtime_requirements": ["env:OPENAI_API_KEY"],
            "env_preflight_missing_env": ["OPENAI_API_KEY"],
            "env_preflight_issue_count": 1,
            "env_consistency": env_consistency,
            "runtime_ready_step_count": 0,
            "runtime_blocked_step_count": 1,
            "env_preflight_verify_issue_count": 0,
            "env_preflight_verify_quality_gate_failure_count": 0,
        }
        source_artifact = tmp_path / "benchmark-verify.json"
        source_artifact.write_text('{"ok": true}\n', encoding="utf-8")
        source_artifacts = {
            "benchmark_verify": {
                "path": str(source_artifact),
                "sha256": hashlib.sha256(source_artifact.read_bytes()).hexdigest(),
            }
        }
        artifact = tmp_path / "offline-readiness.json"
        artifact.write_text(
            json.dumps(
                {
                    "command": "prediction-offline-readiness-summary",
                    "ok": False,
                    "offline_input_ok": True,
                    "live_ready": False,
                    "source_artifacts": source_artifacts,
                    "local_inputs": {},
                    "benchmark": {
                        "ok": True,
                        "component_count": 0,
                        "quality_gate_failure_count": 0,
                    },
                    "env_preflight": {
                        "present": True,
                        "missing_env": ["OPENAI_API_KEY"],
                        "issue_count": 1,
                    },
                    "env_preflight_verify": {
                        "present": True,
                        "ok": True,
                        "issues": [],
                        "issue_count": 0,
                        "quality_gate_failures": [],
                        "quality_gate_failure_count": 0,
                    },
                    "env_consistency": env_consistency,
                    "runtime": {
                        "missing_runtime_requirements": ["env:OPENAI_API_KEY"],
                        "operator_resume_batches": [
                            {
                                "phase": 1,
                                "missing_requirements": ["env:OPENAI_API_KEY"],
                                "actions": ["materialize_missing_bill_semantics"],
                                "source_artifacts": [
                                    str(tmp_path / "prediction-eval-manifest-verify.json")
                                ],
                                "additional_reasons": [
                                    "Eval manifest and backtest both need feature source URLs."
                                ],
                                "commands": [
                                    "python3 -m src.runtime.main "
                                    "materialize-bill-semantics "
                                    "--output-root out/bill-semantics"
                                ],
                            }
                        ],
                        "runtime_ready_step_count": 0,
                        "runtime_blocked_step_count": 1,
                    },
                    "blockers": ["env_preflight_issue:dotenv file not found: .env"],
                    "blocker_count": 1,
                    "blocker_summary": blocker_summary,
                    "issues": [],
                    "issue_count": 0,
                    "resume_script_output": str(script),
                    "resume_script_output_sha256": hashlib.sha256(script.read_bytes()).hexdigest(),
                    "run_metadata": {
                        "command": "prediction-offline-readiness-summary",
                        "source_artifact_sha256": {
                            "benchmark_verify": hashlib.sha256(
                                source_artifact.read_bytes()
                            ).hexdigest()
                        },
                        "source_state": source_state,
                    },
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        output = tmp_path / "offline-readiness-verify.json"

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-offline-readiness-summary",
                artifact=str(artifact),
                require_run_metadata=True,
                require_env_preflight_verify=True,
                require_resume_script_match=True,
                require_no_secret_literals=True,
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is True
        assert result["issue_count"] == 0
        assert result["quality_gate_failure_count"] == 0
        assert result["artifact_sha256"] == hashlib.sha256(artifact.read_bytes()).hexdigest()
        assert result["script_matches_expected"] is True
        assert result["run_metadata"]["source_state"] == {
            "blocker_count": 1,
            "issue_count": 0,
            "operator_resume_batch_count": 1,
            "source_artifact_count": 1,
            "source_artifact_mismatch_count": 0,
            "source_artifact_invalid_count": 0,
            "script_matches_expected": True,
            "secret_literal_count": 0,
            "env_preflight_verify_present": True,
            "env_preflight_verify_ok": True,
        }
        assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
        assert written["run_metadata"] == result["run_metadata"]

        invalid_source_artifact = json.loads(artifact.read_text(encoding="utf-8"))
        invalid_source_artifact["source_artifacts"]["benchmark_verify"]["sha256"] = True
        invalid_source_artifact["run_metadata"]["source_artifact_sha256"]["benchmark_verify"] = True
        artifact.write_text(
            json.dumps(invalid_source_artifact, sort_keys=True),
            encoding="utf-8",
        )

        invalid_source_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-offline-readiness-summary",
                artifact=str(artifact),
                require_run_metadata=True,
                require_env_preflight_verify=True,
                require_resume_script_match=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert invalid_source_result["ok"] is False
        assert (
            "source_artifact_sha256_invalid:benchmark_verify" in (invalid_source_result["issues"])
        )
        assert (
            "source_artifact_sha256_mismatch:benchmark_verify"
            not in (invalid_source_result["issues"])
        )
        assert (
            "run_metadata_source_artifact_sha256_invalid:benchmark_verify"
            in (invalid_source_result["issues"])
        )
        assert (
            "run_metadata_source_artifact_sha256_mismatch" not in (invalid_source_result["issues"])
        )
        assert (
            invalid_source_result["run_metadata"]["source_state"]["source_artifact_invalid_count"]
            == 1
        )

