    def test_dispatch_verify_prediction_offline_readiness_summary_rejects_weak_or_secret_artifact(
        self,
        tmp_path: Path,
    ) -> None:
        script = tmp_path / "prediction-resume.sh"
        script.write_text("#!/usr/bin/env bash\necho unsafe\n", encoding="utf-8")
        source_artifact = tmp_path / "benchmark-verify.json"
        source_artifact.write_text('{"ok": true}\n', encoding="utf-8")
        artifact = tmp_path / "offline-readiness.json"
        artifact.write_text(
            json.dumps(
                {
                    "command": "prediction-offline-readiness-summary",
                    "source_artifacts": {
                        "benchmark_verify": {
                            "path": str(source_artifact),
                            "sha256": "0" * 64,
                        },
                        "missing_source": {
                            "path": str(tmp_path / "missing.json"),
                            "sha256": "1" * 64,
                        },
                    },
                    "blockers": ["runtime:blocked"],
                    "blocker_count": 0,
                    "blocker_summary": {"total": 0},
                    "issues": ["sk-secret-value"],
                    "issue_count": 0,
                    "runtime": {"operator_resume_batches": []},
                    "env_preflight_verify": {
                        "present": True,
                        "ok": False,
                        "issues": ["checked_count_mismatch"],
                        "issue_count": 1,
                        "quality_gate_failures": ["secret_literal:openai_token"],
                        "quality_gate_failure_count": 1,
                    },
                    "resume_script_output": str(script),
                    "resume_script_output_sha256": "0" * 64,
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-offline-readiness-summary",
                artifact=str(artifact),
                require_run_metadata=True,
                require_env_preflight_verify=True,
                require_resume_script_match=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert result["ok"] is False
        assert "blocker_count_mismatch" in result["issues"]
        assert "blocker_summary_total_mismatch" in result["issues"]
        assert "issue_count_mismatch" in result["issues"]
        assert "source_artifact_sha256_mismatch:benchmark_verify" in result["issues"]
        assert "source_artifact_missing:missing_source" in result["issues"]
        assert "run_metadata_missing" in result["quality_gate_failures"]
        assert "env_preflight_verify_not_ok" in result["quality_gate_failures"]
        assert "resume_script_sha256_mismatch" in result["quality_gate_failures"]
        assert "script_content_mismatch" in result["quality_gate_failures"]
        assert "secret_literal:openai_token" in result["quality_gate_failures"]

