        script = tmp_path / "prediction-resume.sh"
        script_text = "\n".join(
            [
                "#!/usr/bin/env bash",
                "set -euo pipefail",
                "",
                "# Generated by prediction-offline-readiness-summary.",
                "# Fill required environment variables locally before running a phase.",
                "# Commands are derived from the verified prediction backfill plan.",
                "",
                "# Phase 1",
                "# Missing requirements: env:OPENAI_API_KEY",
                "# Actions: materialize_missing_bill_semantics",
                "# Source requirements:",
                "#   - Non-Congress bill keys require a jurisdiction-specific bill metadata and semantic materialization adapter before the Congress.gov bill-semantics command can satisfy them.",
                ': "${OPENAI_API_KEY:?Set OPENAI_API_KEY before phase 1}"',
                "python3 -m src.runtime.main materialize-bill-semantics "
                "--output-root out/bill-semantics",
                "",
            ]
        )
        script.write_text(script_text, encoding="utf-8")
        readiness = tmp_path / "offline-readiness.json"
        readiness.write_text(
            json.dumps(
                {
                    "command": "prediction-offline-readiness-summary",
                    "runtime": {
                        "operator_resume_batches": [
                            {
                                "phase": 1,
                                "missing_requirements": ["env:OPENAI_API_KEY"],
                                "actions": ["materialize_missing_bill_semantics"],
                                "source_requirements": [
                                    "Non-Congress bill keys require a jurisdiction-specific bill metadata and semantic materialization adapter before the Congress.gov bill-semantics command can satisfy them."
                                ],
                                "commands": [
                                    "python3 -m src.runtime.main materialize-bill-semantics "
                                    "--output-root out/bill-semantics"
                                ],
                            }
                        ]
                    },
                    "resume_script_output": str(script),
                    "resume_script_output_sha256": hashlib.sha256(script.read_bytes()).hexdigest(),
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        readiness_verify = tmp_path / "offline-readiness-verify.json"
        readiness_verify.write_text(
            json.dumps(
                {
                    "command": "verify-prediction-offline-readiness-summary",
                    "ok": True,
                    "artifact": str(readiness),
                    "artifact_sha256": hashlib.sha256(readiness.read_bytes()).hexdigest(),
                    "issues": [],
                    "issue_count": 0,
                    "quality_gate_failures": [],
                    "quality_gate_failure_count": 0,
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        output = tmp_path / "prediction-resume-verify.json"

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-resume-script",
                readiness_summary=str(readiness),
                readiness_summary_verify=str(readiness_verify),
                script=str(script),
                require_env_guards=True,
                require_no_secret_literals=True,
                require_safe_commands=True,
                output=str(output),
            )
        )
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is True
        assert result["issue_count"] == 0
        assert result["quality_gate_failure_count"] == 0
        assert result["phase_count"] == 1
        assert result["script_sha256"] == hashlib.sha256(script.read_bytes()).hexdigest()
        assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
        assert written["run_metadata"]["command"] == "verify-prediction-resume-script"
        assert written["run_metadata"]["source_state"] == {
            "phase_count": 1,
            "command_count": 1,
            "env_guard_count": 1,
            "readiness_summary_verify_present": True,
            "readiness_summary_verify_ok": True,
            "script_matches_expected": True,
            "secret_literal_count": 0,
            "unsafe_command_count": 0,
        }

        invalid_readiness = json.loads(readiness.read_text(encoding="utf-8"))
        invalid_readiness["resume_script_output_sha256"] = True
        readiness.write_text(json.dumps(invalid_readiness, sort_keys=True), encoding="utf-8")
        invalid_readiness_verify = json.loads(readiness_verify.read_text(encoding="utf-8"))
        invalid_readiness_verify["artifact_sha256"] = True
        readiness_verify.write_text(
            json.dumps(invalid_readiness_verify, sort_keys=True),
            encoding="utf-8",
        )

        invalid_hash_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-resume-script",
                readiness_summary=str(readiness),
                readiness_summary_verify=str(readiness_verify),
                script=str(script),
                require_env_guards=True,
                require_no_secret_literals=True,
                require_safe_commands=True,
                output=None,
            )
        )

        assert invalid_hash_result["ok"] is False
        assert "summary_script_sha256_invalid" in invalid_hash_result["issues"]
        assert "script_sha256_mismatch" not in invalid_hash_result["issues"]
        assert "readiness_summary_verify_artifact_sha256_invalid" in (invalid_hash_result["issues"])
        assert (
            "readiness_summary_verify_artifact_sha256_mismatch"
            not in (invalid_hash_result["issues"])
        )

