    def test_dispatch_verify_prediction_operator_handoff_accepts_linked_verifiers(
        self,
        tmp_path: Path,
        monkeypatch: pytest.MonkeyPatch,
    ) -> None:
        env_verify = tmp_path / "runtime-env-preflight-verify.json"
        env_verify.write_text(
            json.dumps(
                {
                    "command": "verify-runtime-env-preflight",
                    "ok": True,
                    "issues": [],
                    "issue_count": 0,
                    "quality_gate_failures": [],
                    "quality_gate_failure_count": 0,
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        readiness = tmp_path / "offline-readiness.json"
        readiness.write_text(
            json.dumps(
                {
                    "command": "prediction-offline-readiness-summary",
                    "env_preflight": {
                        "missing_env": ["OPENAI_API_KEY"],
                        "next_actions": ["set_env:OPENAI_API_KEY"],
                    },
                    "next_live_actions": ["set:OPENAI_API_KEY"],
                    "next_actions_by_kind": {
                        "env_setup": ["set:OPENAI_API_KEY"],
                        "data_refresh": [],
                        "semantic_materialization": [],
                        "source_repair": [],
                    },
                    "runtime": {
                        "operator_resume_batches": [
                            {
                                "phase": 1,
                                "missing_requirements": ["env:OPENAI_API_KEY"],
                                "actions": ["materialize_missing_bill_semantics"],
                                "source_artifacts": [
                                    str(tmp_path / "prediction-eval-manifest-verify.json")
                                ],
                                "additional_reasons": [
                                    "Eval manifest and backtest both need feature source URLs."
                                ],
                                "commands": [
                                    "python3 -m src.runtime.main "
                                    "materialize-bill-semantics "
                                    "--output-root out/bill-semantics"
                                ],
                            }
                        ]
                    },
                    "run_metadata": {
                        "source_state": {
                            "benchmark_eval_cutoff_bill_signal_row_count": 13,
                            "benchmark_eval_cutoff_cutoff_bill_signal_row_count": 12,
                            "benchmark_eval_cutoff_unknown_availability_bill_signal_row_count": 0,
                            "benchmark_eval_cutoff_excluded_future_bill_signal_row_count": 1,
                            "benchmark_eval_cutoff_unknown_availability_ontology_edge_count": 0,
                            "benchmark_eval_cutoff_excluded_future_ontology_edge_count": 2,
                        }
                    },
                    "source_artifacts": {
                        "env_preflight_verify": {
                            "path": str(env_verify),
                            "sha256": hashlib.sha256(env_verify.read_bytes()).hexdigest(),
                        }
                    },
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        readiness_verify = tmp_path / "offline-readiness-verify.json"
        readiness_verify.write_text(
            json.dumps(
                {
                    "command": "verify-prediction-offline-readiness-summary",
                    "ok": True,
                    "artifact": str(readiness),
                    "artifact_sha256": hashlib.sha256(readiness.read_bytes()).hexdigest(),
                    "issues": [],
                    "issue_count": 0,
                    "quality_gate_failures": [],
                    "quality_gate_failure_count": 0,
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        resume_verify = tmp_path / "resume-verify.json"
        resume_verify.write_text(
            json.dumps(
                {
                    "command": "verify-prediction-resume-script",
                    "ok": True,
                    "readiness_summary": str(readiness),
                    "readiness_summary_verify": {
                        "present": True,
                        "ok": True,
                        "path": str(readiness_verify),
                        "artifact": str(readiness),
                        "artifact_sha256": hashlib.sha256(readiness.read_bytes()).hexdigest(),
                    },
                    "issues": [],
                    "issue_count": 0,
                    "quality_gate_failures": [],
                    "quality_gate_failure_count": 0,
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        output = tmp_path / "operator-handoff-verify.json"
        runbook_output = tmp_path / "operator-runbook.md"
        guarded_outputs = {output, runbook_output}
        seen_temp_targets: set[str] = set()
        original_open = Path.open

        def guarded_open(path: Path, *args: object, **kwargs: object):
            mode = str(args[0]) if args else str(kwargs.get("mode", "r"))
            if path in guarded_outputs and any(flag in mode for flag in ("w", "a", "x", "+")):
                raise AssertionError(f"direct final-path write: {path.name}")
            for final_path in guarded_outputs:
                prefix = f".{final_path.name}."
                if (
                    path.parent == final_path.parent
                    and path.name.startswith(prefix)
                    and path.name.endswith(".tmp")
                ):
                    UUID(path.name.removeprefix(prefix).removesuffix(".tmp"))
                    seen_temp_targets.add(final_path.name)
            return original_open(path, *args, **kwargs)

        monkeypatch.setattr(Path, "open", guarded_open)

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-handoff",
                env_preflight_verify=str(env_verify),
                readiness_summary_verify=str(readiness_verify),
                resume_script_verify=str(resume_verify),
                require_no_secret_literals=True,
                output=str(output),
                runbook_output=str(runbook_output),
            )
        )
        runbook = runbook_output.read_text(encoding="utf-8")

        assert result["ok"] is True
        assert result["issue_count"] == 0
        assert result["quality_gate_failure_count"] == 0
        assert result["chain"] == {
            "env_preflight_verify_ok": True,
            "readiness_summary_verify_ok": True,
            "resume_script_verify_ok": True,
            "readiness_source_env_preflight_verify_matches": True,
            "resume_links_readiness_summary_verify": True,
        }
        assert result["operator_plan"] == {
            "missing_env": ["OPENAI_API_KEY"],
            "env_next_actions": ["set_env:OPENAI_API_KEY"],
            "next_live_actions": ["set:OPENAI_API_KEY"],
            "next_actions_by_kind": {
                "env_setup": ["set:OPENAI_API_KEY"],
                "data_refresh": [],
                "semantic_materialization": [],
                "source_repair": [],
            },
            "eval_window_run": {
                "present": False,
                "ok": False,
                "checked": 0,
                "artifact": None,
                "artifact_sha256": None,
                "plan": None,
                "plan_sha256": None,
                "window_count": 0,
                "expected_window_verifier_count": 0,
                "loaded_verifier_count": 0,
                "missing_verifier_count": 0,
                "failing_verifier_count": 0,
                "stale_field_count": 0,
                "issue_count": 0,
                "quality_gate_failure_count": 0,
            },
            "operator_resume_batch_count": 1,
            "cutoff_audit": {
                "bill_signal_row_count": 13,
                "cutoff_bill_signal_row_count": 12,
                "unknown_availability_bill_signal_row_count": 0,
                "excluded_future_bill_signal_row_count": 1,
                "unknown_availability_ontology_edge_count": 0,
                "excluded_future_ontology_edge_count": 2,
            },
            "operator_resume_batches": [
                {
                    "phase": 1,
                    "missing_requirements": ["env:OPENAI_API_KEY"],
                    "actions": ["materialize_missing_bill_semantics"],
                    "source_artifacts": [str(tmp_path / "prediction-eval-manifest-verify.json")],
                    "additional_reasons": [
                        "Eval manifest and backtest both need feature source URLs."
                    ],
                    "commands": [
                        "python3 -m src.runtime.main "
                        "materialize-bill-semantics "
                        "--output-root out/bill-semantics"
                    ],
                }
            ],
        }
        assert result["run_metadata"]["source_state"] == {
            "verifier_count": 3,
            "all_verifiers_ok": True,
            "chain_issue_count": 0,
            "operator_resume_batch_count": 1,
            "next_live_action_count": 1,
            "secret_literal_count": 0,
            "cutoff_audit_bill_signal_row_count": 13,
            "cutoff_audit_cutoff_bill_signal_row_count": 12,
            "cutoff_audit_unknown_availability_bill_signal_row_count": 0,
            "cutoff_audit_excluded_future_bill_signal_row_count": 1,
            "cutoff_audit_unknown_availability_ontology_edge_count": 0,
            "cutoff_audit_excluded_future_ontology_edge_count": 2,
        }
        assert result["run_metadata"]["source_artifact_sha256"] == {
            "env_preflight_verify": hashlib.sha256(env_verify.read_bytes()).hexdigest(),
            "readiness_summary_verify": hashlib.sha256(readiness_verify.read_bytes()).hexdigest(),
            "resume_script_verify": hashlib.sha256(resume_verify.read_bytes()).hexdigest(),
        }
        assert result["runbook_output"] == str(runbook_output)
        assert (
            result["runbook_output_sha256"]
            == hashlib.sha256(runbook_output.read_bytes()).hexdigest()
        )
        assert "# Prediction Operator Handoff" in runbook
        assert "- Status: green" in runbook
        assert "## Verified Artifacts" in runbook
        assert f"- Env preflight verify: `{env_verify}`" in runbook
        assert hashlib.sha256(env_verify.read_bytes()).hexdigest() in runbook
        assert f"- Readiness summary verify: `{readiness_verify}`" in runbook
        assert hashlib.sha256(readiness_verify.read_bytes()).hexdigest() in runbook
