    def test_dispatch_verify_prediction_operator_runbook_rejects_stale_or_secret_runbook(
        self,
        tmp_path: Path,
    ) -> None:
        handoff_verify = tmp_path / "operator-handoff-verify.json"
        runbook = tmp_path / "operator-runbook.md"
        handoff = {
            "ok": True,
            "command": "verify-prediction-operator-handoff",
            "env_preflight_verify": str(tmp_path / "runtime-env-preflight-verify.json"),
            "readiness_summary_verify": str(tmp_path / "offline-readiness-verify.json"),
            "resume_script_verify": str(tmp_path / "resume-verify.json"),
            "artifact_sha256": {
                "env_preflight_verify": "a" * 64,
                "readiness_summary_verify": "b" * 64,
                "resume_script_verify": "c" * 64,
            },
            "issue_count": 0,
            "quality_gate_failure_count": 0,
            "operator_plan": {},
            "runbook_output": str(runbook),
            "runbook_output_sha256": "0" * 64,
        }
        handoff_verify.write_text(json.dumps(handoff), encoding="utf-8")
        runbook.write_text(
            "# Prediction Operator Handoff\n\nOPENAI_API_KEY=sk-secret\n",
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-runbook",
                handoff_verify=str(handoff_verify),
                runbook=str(runbook),
                require_handoff_runbook_sha=True,
                require_no_secret_literals=True,
                require_verified_artifact_hashes=True,
                output=None,
            )
        )

        assert result["ok"] is False
        assert "runbook_content_mismatch" in result["quality_gate_failures"]
        assert "runbook_sha256_mismatch" in result["quality_gate_failures"]
        assert "secret_literal:openai_token" in result["quality_gate_failures"]
        assert (
            "verified_artifact_missing:env_preflight_verify:path" in result["quality_gate_failures"]
        )
        assert (
            "verified_artifact_missing:env_preflight_verify:sha256"
            in result["quality_gate_failures"]
        )

