    def test_dispatch_verify_prediction_operator_packet_manifest_accepts_matching_manifest(
        self,
        tmp_path: Path,
    ) -> None:
        status_verify = tmp_path / "operator-status-verify.json"
        status = tmp_path / "operator-status.json"
        runbook_verify = tmp_path / "operator-runbook-verify.json"
        handoff_verify = tmp_path / "operator-handoff-verify.json"
        readiness_verify = tmp_path / "offline-readiness-verify.json"
        readiness = tmp_path / "offline-readiness.json"
        for path, command in (
            (readiness, "prediction-offline-readiness-summary"),
            (readiness_verify, "verify-prediction-offline-readiness-summary"),
            (handoff_verify, "verify-prediction-operator-handoff"),
            (runbook_verify, "verify-prediction-operator-runbook"),
            (status, "prediction-operator-status"),
            (status_verify, "verify-prediction-operator-status"),
        ):
            payload: dict[str, Any] = {"command": command, "ok": True}
            if path == readiness:
                payload |= {"blocker_count": 0, "runtime": {"operator_resume_batches": []}}
            if path == readiness_verify:
                payload |= {
                    "artifact": str(readiness),
                    "artifact_sha256": hashlib.sha256(readiness.read_bytes()).hexdigest(),
                }
            if path == handoff_verify:
                payload |= {"readiness_summary_verify": str(readiness_verify)}
            if path == runbook_verify:
                payload |= {"handoff_verify": str(handoff_verify)}
            if path == status:
                payload |= {
                    "status": "ready",
                    "verification_ok": True,
                    "launch_ready": True,
                    "runbook_verify": str(runbook_verify),
                    "handoff_verify": str(handoff_verify),
                    "readiness_summary_verify": str(readiness_verify),
                    "missing_env": [],
                    "blocker_count": 0,
                }
            if path == status_verify:
                payload |= {
                    "artifact": str(status),
                    "artifact_sha256": hashlib.sha256(status.read_bytes()).hexdigest(),
                    "runbook_verify": str(runbook_verify),
                    "runbook_verify_sha256": hashlib.sha256(
                        runbook_verify.read_bytes()
                    ).hexdigest(),
                }
            path.write_text(json.dumps(payload), encoding="utf-8")
        manifest_output = tmp_path / "operator-packet-manifest.json"
        manifest = dispatch_command(
            SimpleNamespace(
                command="prediction-operator-packet-manifest",
                status_verify=str(status_verify),
                require_existing_files=False,
                require_no_secret_literals=True,
                output=str(manifest_output),
            )
        )
        verify_output = tmp_path / "operator-packet-manifest-verify.json"

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-manifest",
                artifact=str(manifest_output),
                status_verify=str(status_verify),
                require_run_metadata=True,
                require_existing_files=False,
                require_no_secret_literals=True,
                output=str(verify_output),
            )
        )

        assert manifest["ok"] is True
        assert result["ok"] is True
        assert result["manifest_matches_recomputed"] is True
        assert result["source_artifact_invalid_count"] == 0
        assert result["source_artifact_mismatch_count"] == 0
        assert result["packet_file_sha256_mismatch_count"] == 0
        assert result["run_metadata"]["source_state"] == {
            "manifest_matches_recomputed": True,
            "source_artifact_invalid_count": 0,
            "source_artifact_mismatch_count": 0,
            "packet_file_sha256_invalid_count": 0,
            "packet_file_sha256_mismatch_count": 0,
            "missing_file_count": manifest["missing_file_count"],
            "secret_literal_count": 0,
        }
        assert result["output_sha256"] == hashlib.sha256(verify_output.read_bytes()).hexdigest()

        invalid_hash_manifest = dict(manifest)
        invalid_hash_manifest["run_metadata"] = dict(manifest["run_metadata"])
        invalid_hash_manifest["run_metadata"]["source_artifact_sha256"] = dict(
            manifest["run_metadata"]["source_artifact_sha256"]
        )
        invalid_hash_manifest["run_metadata"]["source_artifact_sha256"]["status_verify"] = True
        manifest_output.write_text(
            json.dumps(invalid_hash_manifest, sort_keys=True),
            encoding="utf-8",
        )

        invalid_hash_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-manifest",
                artifact=str(manifest_output),
                status_verify=str(status_verify),
                require_run_metadata=True,
                require_existing_files=False,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert invalid_hash_result["ok"] is False
        assert invalid_hash_result["source_artifact_invalid"] == ["status_verify"]
        assert invalid_hash_result["source_artifact_invalid_count"] == 1
        assert "source_artifact_sha256_invalid:status_verify" in invalid_hash_result["issues"]
        assert (
            "source_artifact_sha256_mismatch:status_verify" not in (invalid_hash_result["issues"])
        )

        invalid_packet_file_manifest = dict(manifest)
        invalid_packet_file_manifest["packet_files"] = [
            dict(entry) for entry in manifest["packet_files"]
        ]
        invalid_packet_file_manifest["packet_files"][0]["sha256"] = True
        invalid_packet_file_manifest["run_metadata"] = dict(manifest["run_metadata"])
        manifest_output.write_text(
            json.dumps(invalid_packet_file_manifest, sort_keys=True),
            encoding="utf-8",
        )

        invalid_packet_file_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-manifest",
                artifact=str(manifest_output),
                status_verify=str(status_verify),
                require_run_metadata=True,
                require_existing_files=False,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert invalid_packet_file_result["ok"] is False
        assert invalid_packet_file_result["packet_file_sha256_invalid"] == [
            invalid_packet_file_manifest["packet_files"][0]["name"]
        ]
        assert invalid_packet_file_result["packet_file_sha256_invalid_count"] == 1
        assert invalid_packet_file_result["packet_file_sha256_mismatch_count"] == 0
        assert (
            "packet_file_sha256_invalid:"
            f"{invalid_packet_file_manifest['packet_files'][0]['name']}"
            in invalid_packet_file_result["issues"]
        )
        assert "packet_file_sha256_mismatch" not in invalid_packet_file_result["issues"]

