        for path, command in (
            (readiness, "prediction-offline-readiness-summary"),
            (readiness_verify, "verify-prediction-offline-readiness-summary"),
            (handoff_verify, "verify-prediction-operator-handoff"),
            (runbook_verify, "verify-prediction-operator-runbook"),
            (status, "prediction-operator-status"),
            (status_verify, "verify-prediction-operator-status"),
        ):
            payload: dict[str, Any] = {"command": command, "ok": True}
            if path == readiness:
                payload |= {"blocker_count": 0, "runtime": {"operator_resume_batches": []}}
            if path == readiness_verify:
                payload |= {
                    "artifact": str(readiness),
                    "artifact_sha256": hashlib.sha256(readiness.read_bytes()).hexdigest(),
                }
            if path == handoff_verify:
                payload |= {"readiness_summary_verify": str(readiness_verify)}
            if path == runbook_verify:
                payload |= {"handoff_verify": str(handoff_verify)}
            if path == status:
                payload |= {
                    "status": "ready",
                    "verification_ok": True,
                    "launch_ready": True,
                    "runbook_verify": str(runbook_verify),
                    "handoff_verify": str(handoff_verify),
                    "readiness_summary_verify": str(readiness_verify),
                    "missing_env": [],
                    "blocker_count": 0,
                }
            if path == status_verify:
                payload |= {
                    "artifact": str(status),
                    "artifact_sha256": hashlib.sha256(status.read_bytes()).hexdigest(),
                    "runbook_verify": str(runbook_verify),
                    "runbook_verify_sha256": hashlib.sha256(
                        runbook_verify.read_bytes()
                    ).hexdigest(),
                }
            path.write_text(json.dumps(payload), encoding="utf-8")
        manifest_output = tmp_path / "operator-packet-manifest.json"
        manifest = dispatch_command(
            SimpleNamespace(
                command="prediction-operator-packet-manifest",
                status_verify=str(status_verify),
                require_existing_files=False,
                require_no_secret_literals=True,
                output=None,
            )
        )
        manifest |= {
            "blocker_count": False,
            "secret_literal_count": False,
            "issue_count": False,
            "quality_gate_failure_count": False,
        }
        manifest["run_metadata"]["source_state"] |= {
            "secret_literal_count": False,
        }
        manifest_output.write_text(json.dumps(manifest, sort_keys=True), encoding="utf-8")

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-manifest",
                artifact=str(manifest_output),
                status_verify=str(status_verify),
                require_run_metadata=True,
                require_existing_files=False,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert result["ok"] is False
        assert "blocker_count must be an integer" in result["issues"]
        assert "secret_literal_count must be an integer" in result["issues"]
        assert "issue_count must be an integer" in result["issues"]
        assert "quality_gate_failure_count must be an integer" in result["issues"]
        assert (
            "run_metadata.source_state.secret_literal_count must be an integer"
            in (result["issues"])
        )

