        output = tmp_path / "operator-packet-export.json"
        expected_final_paths = {
            target_dir / "packet-export-manifest.json",
            target_dir / "README.md",
            target_dir / "verify_packet.py",
            target_dir / "resume_plan.py",
            target_dir / "run_resume.py",
            target_dir / "verify_run_resume.py",
            target_dir / "SHA256SUMS",
            output,
        }
        seen_temp_targets: set[str] = set()
        original_open = Path.open

        def guarded_open(path: Path, *args: object, **kwargs: object):
            mode = str(args[0]) if args else str(kwargs.get("mode", "r"))
            if path in expected_final_paths and any(flag in mode for flag in ("w", "a", "x", "+")):
                raise AssertionError(f"direct packet final-path write: {path.name}")
            for final_path in expected_final_paths:
                prefix = f".{final_path.name}."
                if (
                    path.parent == final_path.parent
                    and path.name.startswith(prefix)
                    and path.name.endswith(".tmp")
                ):
                    token = path.name.removeprefix(prefix).removesuffix(".tmp")
                    UUID(token)
                    seen_temp_targets.add(final_path.name)
            return original_open(path, *args, **kwargs)

        monkeypatch.setattr(Path, "open", guarded_open)

