    def test_dispatch_prediction_operator_packet_export_preserves_selected_sample_scope(
        self,
        tmp_path: Path,
    ) -> None:
        packet_manifest = tmp_path / "operator-packet-manifest.json"
        selected_sample_state = {
            "eval_window_run_requires_training_labels": True,
            "eval_window_run_requires_evaluation_labels": True,
            **_operator_eval_window_run_strict_gate_state(),
            "congress_load_required": True,
            "congress_load_present": True,
            "congress_load_ok": True,
            "congress_load_prediction_member_inputs_available": True,
            "congress_load_prediction_bill_inputs_available": True,
            "congress_load_prediction_vote_inputs_available": False,
            "congress_load_source_family_ids": ["committee_membership", "congress_bill"],
            "selected_sample_vote_event_ids": [101],
            "selected_sample_bill_keys": ["state_ca:2025:ab:1"],
            "selected_sample_member_bioguide_ids": ["CA-A001"],
            "selected_sample_jurisdiction_ids": ["state_ca"],
            "selected_sample_legislative_body_ids": ["state_ca:ca_assembly"],
            "selected_sample_legislative_session_ids": ["state_ca:ca_assembly:2025"],
            "selected_sample_source_family_ids": ["legislative_bill", "legislative_vote"],
        }
        packet_manifest.write_text(
            json.dumps(
                {
                    "command": "prediction-operator-packet-manifest",
                    "ok": True,
                    "packet_files": [],
                    "packet_file_count": 0,
                    "missing_files": [],
                    "missing_file_count": 0,
                    "secret_literal_count": 0,
                    "run_metadata": {"source_state": selected_sample_state},
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        manifest_verify = tmp_path / "operator-packet-manifest-verify.json"
        manifest_verify.write_text(
            json.dumps(
                {
                    "command": "verify-prediction-operator-packet-manifest",
                    "ok": True,
                    "artifact": str(packet_manifest),
                    "artifact_sha256": hashlib.sha256(packet_manifest.read_bytes()).hexdigest(),
                    "run_metadata": {"source_state": selected_sample_state},
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        target_dir = tmp_path / "packet"
        export_output = tmp_path / "operator-packet-export.json"

        export = dispatch_command(
            SimpleNamespace(
                command="prediction-operator-packet-export",
                manifest_verify=str(manifest_verify),
                target_dir=str(target_dir),
                require_no_secret_literals=True,
                output=str(export_output),
            )
        )
        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-export",
                artifact=str(export_output),
                require_run_metadata=True,
                require_export_manifest=True,
                require_exported_files=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert export["ok"] is True
        assert export["run_metadata"]["source_state"]["selected_sample_jurisdiction_ids"] == [
            "state_ca"
        ]
        assert result["ok"] is True, result["issues"]
        assert result["run_metadata"]["source_state"]["selected_sample_bill_keys"] == [
            "state_ca:2025:ab:1"
        ]
        assert (
            result["run_metadata"]["source_state"]["eval_window_run_requires_training_labels"]
            is True
        )
        assert (
            result["run_metadata"]["source_state"]["eval_window_run_requires_evaluation_labels"]
            is True
        )

        malformed_export = json.loads(export_output.read_text(encoding="utf-8"))
        malformed_export["run_metadata"]["source_state"] |= {
            "selected_sample_vote_event_ids": [101, True],
            "eval_window_run_requires_training_labels": "yes",
            "selected_sample_member_bioguide_ids": [" CA-A001"],
            "selected_sample_legislative_body_ids": ["ca_assembly"],
            "selected_sample_legislative_session_ids": ["state_ca:2025_regular"],
            "selected_sample_source_family_ids": ["Congress Vote"],
            "congress_load_source_family_ids": ["Congress Vote"],
        }
        export_output.write_text(json.dumps(malformed_export, sort_keys=True), encoding="utf-8")

        malformed_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-export",
                artifact=str(export_output),
                require_run_metadata=True,
                require_export_manifest=True,
                require_exported_files=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert malformed_result["ok"] is False
        assert (
            "run_metadata.source_state.selected_sample_vote_event_ids must be a list of non-negative integers"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.selected_sample_member_bioguide_ids must be a sorted unique list of non-empty strings"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.selected_sample_source_family_ids must contain normalized source family ids"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.congress_load_source_family_ids must contain normalized source family ids"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.selected_sample_legislative_body_ids must contain scoped ids"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.selected_sample_legislative_session_ids must contain scoped ids"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.eval_window_run_requires_training_labels must be a boolean"
            in malformed_result["issues"]
        )
        assert (
            "run_metadata.source_state.selected_sample_vote_event_ids unexpected"
            not in (malformed_result["issues"])
        )

