    def test_dispatch_verify_prediction_operator_packet_directory_preserves_selected_sample_scope(
        self,
        tmp_path: Path,
    ) -> None:
        packet_dir = tmp_path / "packet"
        files_dir = packet_dir / "files"
        files_dir.mkdir(parents=True)
        exported = files_dir / "operator_status.json"
        exported.write_text(
            json.dumps({"command": "prediction-operator-status", "ok": True}),
            encoding="utf-8",
        )
        selected_sample_state = {
            "eval_window_run_requires_training_labels": True,
            "eval_window_run_requires_evaluation_labels": True,
            "congress_load_required": True,
            "congress_load_present": True,
            "congress_load_ok": True,
            "congress_load_prediction_member_inputs_available": True,
            "congress_load_prediction_bill_inputs_available": True,
            "congress_load_prediction_vote_inputs_available": False,
            "congress_load_source_family_ids": ["committee_membership", "congress_bill"],
            "selected_sample_vote_event_ids": [101],
            "selected_sample_bill_keys": ["state_ca:2025:ab:1"],
            "selected_sample_member_bioguide_ids": ["CA-A001"],
            "selected_sample_jurisdiction_ids": ["state_ca"],
            "selected_sample_legislative_body_ids": ["state_ca:ca_assembly"],
            "selected_sample_legislative_session_ids": ["state_ca:ca_assembly:2025"],
            "selected_sample_source_family_ids": ["legislative_bill", "legislative_vote"],
        }
        manifest = packet_dir / "packet-export-manifest.json"
        manifest_payload = {
            "command": "prediction-operator-packet-export-manifest",
            "exported_files": [
                {
                    "name": "operator_status",
                    "exported_path": "/old/location/files/operator_status.json",
                    "exported_sha256": hashlib.sha256(exported.read_bytes()).hexdigest(),
                    "bytes": exported.stat().st_size,
                }
            ],
            "exported_file_count": 1,
            "skipped_file_count": 0,
            "secret_literal_count": 0,
            "run_metadata": {"source_state": selected_sample_state},
        }
        manifest.write_text(json.dumps(manifest_payload, sort_keys=True), encoding="utf-8")
        readme = packet_dir / "README.md"
        readme.write_text("# Prediction Operator Packet\n", encoding="utf-8")
        checksums = packet_dir / "SHA256SUMS"
        checksums.write_text(
            f"{hashlib.sha256(manifest.read_bytes()).hexdigest()}  packet-export-manifest.json\n"
            f"{hashlib.sha256(readme.read_bytes()).hexdigest()}  README.md\n"
            f"{hashlib.sha256(exported.read_bytes()).hexdigest()}  files/operator_status.json\n",
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-directory",
                packet_dir=str(packet_dir),
                require_readme=True,
                require_checksums=True,
                require_exported_files=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert result["ok"] is True
        assert result["run_metadata"]["source_state"]["selected_sample_jurisdiction_ids"] == [
            "state_ca"
        ]
        assert result["run_metadata"]["source_state"]["selected_sample_bill_keys"] == [
            "state_ca:2025:ab:1"
        ]
        assert result["run_metadata"]["source_state"]["selected_sample_source_family_ids"] == [
            "legislative_bill",
            "legislative_vote",
        ]
        assert result["run_metadata"]["source_state"]["congress_load_source_family_ids"] == [
            "committee_membership",
            "congress_bill",
        ]
        assert (
            result["run_metadata"]["source_state"]["congress_load_prediction_vote_inputs_available"]
            is False
        )
        assert (
            result["run_metadata"]["source_state"]["eval_window_run_requires_training_labels"]
            is True
        )
        assert (
            result["run_metadata"]["source_state"]["eval_window_run_requires_evaluation_labels"]
            is True
        )

        manifest_payload["run_metadata"]["source_state"] |= {
            "selected_sample_vote_event_ids": [101, True],
            "eval_window_run_requires_evaluation_labels": "yes",
            "selected_sample_member_bioguide_ids": [" CA-A001"],
            "selected_sample_source_family_ids": ["legislative_vote", "legislative_bill"],
            "congress_load_source_family_ids": ["Congress Vote"],
        }
        manifest.write_text(json.dumps(manifest_payload, sort_keys=True), encoding="utf-8")

        malformed_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-packet-directory",
                packet_dir=str(packet_dir),
                require_readme=True,
                require_checksums=True,
                require_exported_files=True,
                require_no_secret_literals=True,
                output=None,
            )
        )

        assert malformed_result["ok"] is False
        assert (
            "export_manifest.run_metadata.source_state.selected_sample_vote_event_ids must be a list of non-negative integers"
            in malformed_result["issues"]
        )
        assert (
            "export_manifest.run_metadata.source_state.selected_sample_member_bioguide_ids must be a sorted unique list of non-empty strings"
            in malformed_result["issues"]
        )
        assert (
            "export_manifest.run_metadata.source_state.selected_sample_source_family_ids must be a sorted unique list of non-empty strings"
            in malformed_result["issues"]
        )
        assert (
            "export_manifest.run_metadata.source_state.congress_load_source_family_ids must contain normalized source family ids"
            in malformed_result["issues"]
        )
        assert (
            "export_manifest.run_metadata.source_state.eval_window_run_requires_evaluation_labels must be a boolean"
            in malformed_result["issues"]
        )

