    def test_dispatch_verify_prediction_operator_resume_plan_rejects_boolean_counts(
        self,
        tmp_path: Path,
        monkeypatch: pytest.MonkeyPatch,
    ) -> None:
        monkeypatch.delenv("OPENAI_API_KEY", raising=False)
        dotenv = tmp_path / ".env"
        dotenv.write_text("OPENAI_API_KEY=test-key\n", encoding="utf-8")
        packet_dir = tmp_path / "packet"
        files_dir = packet_dir / "files"
        files_dir.mkdir(parents=True)
        resume_script = files_dir / "resume_script.sh"
        resume_script.write_text(
            "\n".join(
                [
                    "#!/usr/bin/env bash",
                    "set -euo pipefail",
                    "",
                    "# Phase 1",
                    "# Missing requirements: env:OPENAI_API_KEY",
                    "# Actions: materialize_missing_bill_semantics",
                    ': "${OPENAI_API_KEY:?Set OPENAI_API_KEY before phase 1}"',
                    "python3 -m src.runtime.main materialize-bill-semantics --dry-run",
                    "",
                ]
            ),
            encoding="utf-8",
        )
        manifest = packet_dir / "packet-export-manifest.json"
        manifest.write_text(
            json.dumps(
                {
                    "command": "prediction-operator-packet-export-manifest",
                    "exported_files": [
                        {
                            "name": "resume_script",
                            "exported_path": "/old/location/files/resume_script.sh",
                            "exported_sha256": hashlib.sha256(
                                resume_script.read_bytes()
                            ).hexdigest(),
                            "bytes": resume_script.stat().st_size,
                        }
                    ],
                    "exported_file_count": 1,
                    "skipped_file_count": 0,
                    "secret_literal_count": 0,
                }
            ),
            encoding="utf-8",
        )
        readme = packet_dir / "README.md"
        readme.write_text("# Prediction Operator Packet\n", encoding="utf-8")
        checksums = packet_dir / "SHA256SUMS"
        checksums.write_text(
            f"{hashlib.sha256(manifest.read_bytes()).hexdigest()}  packet-export-manifest.json\n"
            f"{hashlib.sha256(readme.read_bytes()).hexdigest()}  README.md\n"
            f"{hashlib.sha256(resume_script.read_bytes()).hexdigest()}  files/resume_script.sh\n",
            encoding="utf-8",
        )
        plan = dispatch_command(
            SimpleNamespace(
                command="prediction-operator-resume-plan",
                packet_dir=str(packet_dir),
                dotenv=str(dotenv),
                require_verified_packet=True,
                require_no_secret_literals=True,
                output=None,
            )
        )
        plan["phase_count"] = True
        plan["command_count"] = True
        plan["runnable_phase_count"] = True
        plan["blocked_phase_count"] = False
        plan["secret_literal_count"] = False
        plan["dotenv"]["dotenv_only_count"] = True
        plan["run_metadata"]["source_state"] |= {
            "phase_count": True,
            "command_count": True,
            "blocked_phase_count": False,
            "dotenv_only_count": True,
            "secret_literal_count": False,
        }
        artifact = tmp_path / "operator-resume-plan.json"
        artifact.write_text(json.dumps(plan, sort_keys=True), encoding="utf-8")

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-operator-resume-plan",
                artifact=str(artifact),
                require_run_metadata=True,
                require_matches_current_packet=True,
                require_no_secret_literals=True,
                require_launch_ready=False,
                output=None,
            )
        )

        assert result["ok"] is False
        assert "phase_count must be an integer" in result["issues"]
        assert "command_count must be an integer" in result["issues"]
        assert "runnable_phase_count must be an integer" in result["issues"]
        assert "blocked_phase_count must be an integer" in result["issues"]
        assert "secret_literal_count must be an integer" in result["issues"]
        assert "dotenv.dotenv_only_count must be an integer" in result["issues"]

