    def test_dispatch_verify_prediction_backfill_plan_passes_complete_plan(
        self,
        tmp_path: Path,
    ) -> None:
        artifact = tmp_path / "benchmark-verify.json"
        artifact.write_text(
            json.dumps(
                {
                    "command": "verify-prediction-benchmark",
                    "backfill_plan": {
                        "step_count": 2,
                        "source_eval_manifest": "out/eval-manifest.json",
                        "source_eval_report": "out/eval-report.json",
                        "steps": [
                            {
                                "action": "load_missing_bill_metadata",
                                "priority_score": 40,
                                "affected_case_count": 1,
                                "reason": "Bill metadata is missing.",
                                "missing_bill_keys": ["118-hr-550"],
                                "unavailable_signal_counts": {},
                                "sample_vote_event_ids": [],
                                "blocked_by": [],
                                "source_requirements": [
                                    "Load official Congress.gov bill metadata."
                                ],
                                "runtime_requirements": [
                                    "env:OPENPACT_POSTGRES_DSN",
                                    "env:OPENPACT_CONGRESS_API_KEY",
                                ],
                                "suggested_commands": [
                                    "python3 -m src.runtime.main load-congress --congress 118"
                                ],
                            },
                            {
                                "action": "materialize_missing_bill_semantics",
                                "priority_score": 30,
                                "affected_case_count": 2,
                                "reason": "Bill semantics are missing.",
                                "missing_bill_keys": ["118-hr-550", "119-hr-1"],
                                "unavailable_signal_counts": {},
                                "sample_vote_event_ids": [],
                                "blocked_by": ["load_missing_bill_metadata"],
                                "source_requirements": ["Use cutoff-available bill metadata."],
                                "runtime_requirements": [
                                    "env:OPENPACT_POSTGRES_DSN",
                                    "env:OPENAI_API_KEY",
                                    "file:out/eval-report.json",
                                ],
                                "suggested_commands": [
                                    "python3 -m src.runtime.main materialize-bill-semantics "
                                    "--output-root out/bill-semantics "
                                    "--missing-from-report out/eval-report.json --model gpt-5.5",
                                    "python3 -m src.runtime.main verify-bill-semantics "
                                    "--root out/bill-semantics --require-model-name gpt-5.5 "
                                    "--require-source-inputs-sha256 "
                                    "--output out/bill-semantics-verify.json",
                                ],
                            },
                        ],
                    },
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-backfill-plan",
                artifact=str(artifact),
                require_source_requirements=True,
                require_runtime_requirements=True,
                require_supported_suggested_commands=True,
                require_blocker_links=True,
                output=str(tmp_path / "backfill-plan-verify.json"),
            )
        )

        written = json.loads(Path(result["output"]).read_text(encoding="utf-8"))
        assert result["ok"] is True
        assert result["issue_count"] == 0
        assert result["quality_gate_failure_count"] == 0
        assert written["issue_count"] == 0
        assert written["quality_gate_failure_count"] == 0
        assert result["step_count"] == 2
        assert result["supported_command_step_count"] == 2
        assert (
            result["output_sha256"]
            == hashlib.sha256(Path(result["output"]).read_bytes()).hexdigest()
        )
        assert written["run_metadata"]["command"] == "verify-prediction-backfill-plan"
        assert written["run_metadata"]["source_state"] == {
            "step_count": 2,
            "declared_step_count": 2,
            "supported_command_step_count": 2,
            "action_names": [
                "load_missing_bill_metadata",
                "materialize_missing_bill_semantics",
            ],
            "source_eval_manifest": "out/eval-manifest.json",
            "source_eval_report": "out/eval-report.json",
            "runtime_requirement_count": 5,
            "missing_runtime_requirements": [],
            "missing_runtime_requirement_step_count": 0,
            "missing_runtime_requirements_by_step": [],
            "runtime_ready_step_count": 0,
            "runtime_blocked_step_count": 0,
            "runtime_readiness_by_step": [],
            "sample_case_count": 0,
            "sample_vote_event_ids": [],
            "sample_bill_keys": [],
            "sample_member_bioguide_ids": [],
            "sample_jurisdiction_ids": [],
            "sample_legislative_body_ids": [],
            "sample_legislative_session_ids": [],
            "sample_source_family_ids": [],
        }

