    def test_run_prediction_eval_report_command_loads_bill_semantics_cache(self) -> None:
        bill_semantics_root = Path("/tmp/openpact-bill-semantics")
        training_feature_cutoff = dt.date(2022, 12, 31)
        train_start = dt.date(2023, 1, 1)
        train_end = dt.date(2024, 12, 31)
        feature_cutoff = dt.date(2024, 12, 31)
        label_start = dt.date(2025, 1, 1)
        label_end = dt.date(2026, 12, 31)

        with (
            patch(f"{_MODULE}.open_connection", return_value=sentinel.conn),
            patch(
                f"{_MODULE}.fetch_vote_prediction_backtest_feature_rows",
                side_effect=[[sentinel.training_feature], [sentinel.evaluation_feature]],
            ),
            patch(
                f"{_MODULE}.fetch_vote_prediction_backtest_label_rows",
                side_effect=[[sentinel.training_label], [sentinel.evaluation_label]],
            ),
            patch(f"{_MODULE}.fetch_all_ontology_edge_rows", return_value=[]),
            patch(f"{_MODULE}.fetch_vote_prediction_backtest_bill_signal_rows", return_value=[]),
            patch(f"{_MODULE}.fetch_vote_prediction_contribution_signal_rows", return_value=[]),
            patch(f"{_MODULE}.fetch_vote_prediction_statement_signal_rows", return_value=[]),
            patch(
                f"{_MODULE}.load_bill_semantic_payloads",
                return_value=[sentinel.bill_semantic],
            ) as load_semantics,
            patch(f"{_MODULE}.build_prediction_eval_report", return_value=sentinel.report) as build,
        ):
            result = run_prediction_eval_report_command(
                sentinel.ctx,
                training_feature_cutoff=training_feature_cutoff,
                train_start=train_start,
                train_end=train_end,
                feature_cutoff=feature_cutoff,
                label_start=label_start,
                label_end=label_end,
                bill_semantics_root=bill_semantics_root,
            )

        load_semantics.assert_called_once_with(bill_semantics_root)
        assert build.call_args.kwargs["bill_semantics"] == [sentinel.bill_semantic]
        assert result is sentinel.report

    def test_dispatch_prediction_eval_report_writes_integrated_report(self, tmp_path: Path) -> None:
        report = build_prediction_eval_report(
            training_feature_cutoff=dt.date(2022, 12, 31),
            train_start=dt.date(2023, 1, 1),
            train_end=dt.date(2024, 12, 31),
            feature_cutoff=dt.date(2024, 12, 31),
            label_start=dt.date(2025, 1, 1),
            label_end=dt.date(2025, 12, 31),
            training_feature_rows=[],
            evaluation_feature_rows=[],
            training_label_rows=[],
            evaluation_label_rows=[],
            ontology_edges=[],
            bill_signal_rows=[],
        )
        output = tmp_path / "prediction-eval-report.json"
        dataset_output = tmp_path / "prediction-eval-dataset.json"
        manifest_output = tmp_path / "prediction-eval-manifest.json"
        congress_archive_manifest = tmp_path / "congress-manifest.json"
        congress_archive_manifest.write_text(
            json.dumps({"congress": 119}, sort_keys=True),
            encoding="utf-8",
        )
        congress_archive_manifest_metadata = {
            "path": str(congress_archive_manifest),
            "sha256": hashlib.sha256(congress_archive_manifest.read_bytes()).hexdigest(),
        }
        bill_semantics_root = tmp_path / "bill-semantics"
        bill_semantics_root.mkdir()
        bill_semantics_index = bill_semantics_root / "index.json"
        bill_semantics_index.write_text(
            json.dumps(
                {
                    "bill_count": 2,
                    "bills": [
                        {"bill_key": "119-hr-1", "model_name": "gpt-5.5"},
                        {"bill_key": "119-s-2", "model_name": "gpt-5.4-mini"},
                    ],
                },
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        bill_semantics_index_sha256 = hashlib.sha256(bill_semantics_index.read_bytes()).hexdigest()
        with (
            patch(f"{_MODULE}.build_runtime", return_value=SimpleNamespace(context=sentinel.ctx)),
            patch(f"{_MODULE}.run_prediction_eval_report_command", return_value=report),
        ):
            result = dispatch_command(
                SimpleNamespace(
                    command="prediction-eval-report",
                    training_feature_cutoff=dt.date(2022, 12, 31),
                    train_start=dt.date(2023, 1, 1),
                    train_end=dt.date(2024, 12, 31),
                    feature_cutoff=dt.date(2024, 12, 31),
                    label_start=dt.date(2025, 1, 1),
                    label_end=dt.date(2025, 12, 31),
                    bill_semantics_root=str(bill_semantics_root),
                    congress_archive_manifest=str(congress_archive_manifest),
                    output=str(output),
                    dataset_output=str(dataset_output),
                    manifest_output=str(manifest_output),
                    strict_readiness=True,
                    min_training_examples=10,
                    min_evaluation_examples=2,
                    min_bill_metadata_coverage_rate=0.9,
                    fail_on_mixed_bill_semantics_models=True,
                )
            )

