        assert manifest_written["artifacts"]["dataset"]["path"] == str(dataset_output)
        assert manifest_written["artifacts"]["dataset"]["sha256"] == result["dataset_output_sha256"]
        assert manifest_written["run_metadata"] == written["run_metadata"]
        assert manifest_written["quality"]["readiness_status"] == "blocked"
        assert manifest_written["quality"]["thresholds"] == {
            "min_training_examples": 10,
            "min_evaluation_examples": 2,
            "min_bill_semantic_coverage_rate": None,
            "min_bill_metadata_coverage_rate": 0.9,
            "min_training_bill_semantic_coverage_rate": None,
            "min_evaluation_bill_semantic_coverage_rate": None,
            "min_training_feature_source_coverage_rate": None,
            "min_evaluation_feature_source_coverage_rate": None,
            "min_training_feature_source_url_coverage_rate": None,
            "min_training_feature_official_source_coverage_rate": None,
            "min_evaluation_feature_source_url_coverage_rate": None,
            "min_evaluation_feature_official_source_coverage_rate": None,
            "min_evaluation_source_url_coverage_rate": None,
            "fail_on_unknown_bill_semantic_availability": False,
            "fail_on_unknown_bill_signal_availability": False,
            "fail_on_unknown_ontology_edge_availability": False,
            "fail_on_unknown_contribution_signal_availability": False,
            "fail_on_unknown_statement_signal_availability": False,
            "fail_on_mixed_bill_semantics_models": True,
        }
        assert (
            "mixed_bill_semantics_models"
            in manifest_written["quality"]["readiness_warning_reasons"]
        )
        assert manifest_written["source_state"] == written["run_metadata"]["source_state"]
        assert manifest_written["learned_model"]["signal_count"] == 0
        assert manifest_written["learned_model"]["top_signal_coefficients"] == []
        verify_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-eval-manifest",
                manifest=str(manifest_output),
            )
        )
        assert verify_result["ok"] is True
        assert verify_result["issues"] == []

        manifest_metadata_mismatch = tmp_path / "manifest-metadata-mismatch.json"
        manifest_metadata_payload = dict(manifest_written)
        manifest_metadata_payload["run_metadata"] = dict(manifest_written["run_metadata"])
        manifest_metadata_payload["run_metadata"]["label_end"] = "2025-12-30"
        manifest_metadata_mismatch.write_text(
            json.dumps(manifest_metadata_payload, sort_keys=True),
            encoding="utf-8",
        )
        manifest_metadata_mismatch_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-eval-manifest",
                manifest=str(manifest_metadata_mismatch),
                require_artifact_run_metadata=True,
            )
        )
        assert manifest_metadata_mismatch_result["ok"] is False
        assert any(
            "manifest run_metadata mismatch" in issue
            for issue in manifest_metadata_mismatch_result["issues"]
        )

        written["run_metadata"]["command"] = "prediction-backtest"
        output.write_text(json.dumps(written, sort_keys=True), encoding="utf-8")
        manifest_written["artifacts"]["report"]["sha256"] = hashlib.sha256(
            output.read_bytes()
        ).hexdigest()
        manifest_output.write_text(
            json.dumps(manifest_written, sort_keys=True),
            encoding="utf-8",
        )

        command_mismatch_result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-eval-manifest",
                manifest=str(manifest_output),
                require_artifact_run_metadata=True,
            )
        )

        assert command_mismatch_result["ok"] is False
        assert any(
            "report: run_metadata mismatch" in issue
            and "'command': 'prediction-eval-report'" in issue
            for issue in command_mismatch_result["issues"]
        )

