        assert "manifest source_state mismatch: implemented_jurisdiction_count" in result["issues"]
        assert "manifest source_state mismatch: portable_jurisdiction_count" in result["issues"]
        assert "manifest source_state mismatch: legislative_body_count" in result["issues"]
