    def test_dispatch_verify_prediction_eval_manifest_skips_cache_model_names_for_invalid_input_model_names(
        self,
        tmp_path: Path,
    ) -> None:
        cases = [
            (
                "duplicate",
                ["gpt-5.5", "gpt-5.5"],
                "manifest inputs bill_semantics_model_names must be unique",
            ),
            (
                "blank",
                [""],
                "manifest inputs bill_semantics_model_names must be non-empty",
            ),
            (
                "untrimmed",
                [" gpt-5.5 "],
                "manifest inputs bill_semantics_model_names must be trimmed",
            ),
        ]
        for case_name, model_names, expected_issue in cases:
            case_dir = tmp_path / case_name
            case_dir.mkdir()
            report = case_dir / "report.json"
            dataset = case_dir / "dataset.json"
            report.write_text('{"report": true}', encoding="utf-8")
            dataset.write_text('{"dataset": true}', encoding="utf-8")
            bill_semantics_root = case_dir / "bill-semantics"
            bill_semantics_root.mkdir()
            index_path = bill_semantics_root / "index.json"
            index_path.write_text(
                json.dumps(
                    {"bill_count": 0, "bills": [], "model_names": []},
                    sort_keys=True,
                ),
                encoding="utf-8",
            )
            manifest = case_dir / "manifest.json"
            manifest.write_text(
                json.dumps(
                    {
                        "command": "prediction-eval-report",
                        "inputs": {
                            "bill_semantics_root": str(bill_semantics_root),
                            "bill_semantics_index_sha256": hashlib.sha256(
                                index_path.read_bytes()
                            ).hexdigest(),
                            "bill_semantics_model_names": model_names,
                        },
                        "artifacts": {
                            "report": {
                                "path": str(report),
                                "sha256": hashlib.sha256(report.read_bytes()).hexdigest(),
                            },
                            "dataset": {
                                "path": str(dataset),
                                "sha256": hashlib.sha256(dataset.read_bytes()).hexdigest(),
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )

            result = dispatch_command(
                SimpleNamespace(
                    command="verify-prediction-eval-manifest",
                    manifest=str(manifest),
                )
            )

            assert result["ok"] is False
            assert expected_issue in result["issues"]
            assert not any(
                issue.startswith("bill-semantics index: model_names mismatch")
                for issue in result["issues"]
            )

    def test_dispatch_verify_prediction_eval_manifest_requires_prediction_eval_command(
        self,
        tmp_path: Path,
    ) -> None:
        manifest = tmp_path / "manifest.json"
        manifest.write_text(
            json.dumps({"command": "other-command", "artifacts": {"report": {}, "dataset": {}}}),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-eval-manifest",
                manifest=str(manifest),
            )
        )

        assert result["ok"] is False
        assert "manifest command must be prediction-eval-report" in result["issues"]

    def test_dispatch_verify_prediction_eval_manifest_requires_report_and_dataset(
        self,
        tmp_path: Path,
    ) -> None:
        report = tmp_path / "report.json"
        report.write_text('{"report": true}', encoding="utf-8")
        manifest = tmp_path / "manifest.json"
        manifest.write_text(
            json.dumps(
                {
                    "command": "prediction-eval-report",
                    "artifacts": {
                        "report": {
                            "path": str(report),
                            "sha256": hashlib.sha256(report.read_bytes()).hexdigest(),
                        }
                    },
                }
            ),
            encoding="utf-8",
        )

        result = dispatch_command(
            SimpleNamespace(
                command="verify-prediction-eval-manifest",
                manifest=str(manifest),
                output=str(tmp_path / "eval-manifest-verify.json"),
            )
        )
        output = Path(result["output"])
        written = json.loads(output.read_text(encoding="utf-8"))

        assert result["ok"] is False
        assert written["ok"] is False
        assert (
            written["run_metadata"]["artifact_sha256"]
            == hashlib.sha256(manifest.read_bytes()).hexdigest()
        )
        assert written["run_metadata"]["source_artifact_sha256"] == {
            "report": hashlib.sha256(report.read_bytes()).hexdigest(),
        }
        assert "dataset: missing artifact entry" in result["issues"]

