def test_dispatch_prediction_eval_report_rejects_invalid_coverage_thresholds_before_writing(
    tmp_path: Path,
) -> None:
    output = tmp_path / "prediction-eval-report.json"
    dataset_output = tmp_path / "prediction-eval-dataset.json"
    manifest_output = tmp_path / "prediction-eval-manifest.json"
    run_report = MagicMock()

    with (
        patch(f"{_MODULE}.build_runtime", return_value=SimpleNamespace(context=sentinel.ctx)),
        patch(f"{_MODULE}.run_prediction_eval_report_command", run_report),
    ):
        result = dispatch_command(
            SimpleNamespace(
                command="prediction-eval-report",
                training_feature_cutoff=dt.date(2022, 12, 31),
                train_start=dt.date(2023, 1, 1),
                train_end=dt.date(2024, 12, 31),
                feature_cutoff=dt.date(2024, 12, 31),
                label_start=dt.date(2025, 1, 1),
                label_end=dt.date(2025, 12, 31),
                bill_semantics_root=None,
                output=str(output),
                dataset_output=str(dataset_output),
                manifest_output=str(manifest_output),
                strict_readiness=False,
                min_training_examples=-1,
                min_evaluation_examples=True,
                min_bill_semantic_coverage_rate=-0.1,
                min_bill_metadata_coverage_rate=1.1,
                min_training_bill_semantic_coverage_rate=True,
                min_evaluation_bill_semantic_coverage_rate=None,
                min_training_feature_source_coverage_rate=None,
                min_evaluation_feature_source_coverage_rate=None,
                min_training_feature_source_url_coverage_rate=None,
                min_training_feature_official_source_coverage_rate=None,
                min_evaluation_feature_source_url_coverage_rate=None,
                min_evaluation_feature_official_source_coverage_rate=None,
                min_evaluation_source_url_coverage_rate=None,
                fail_on_unknown_bill_semantic_availability=False,
                fail_on_unknown_ontology_edge_availability=False,
            )
        )

    assert result["ok"] is False
    assert result["issues"] == [
        "min_training_examples must be a non-negative integer",
        "min_evaluation_examples must be a non-negative integer",
        "min_bill_semantic_coverage_rate must be a number between 0 and 1",
        "min_bill_metadata_coverage_rate must be a number between 0 and 1",
        "min_training_bill_semantic_coverage_rate must be a number between 0 and 1",
    ]
    assert result["issue_count"] == 5
    assert result["quality_gate_failures"] == []
    run_report.assert_not_called()
    assert not output.exists()
    assert not dataset_output.exists()
    assert not manifest_output.exists()


