    assert "verify-prediction-eval-window-run" in result["verify_run_command"]
    assert f"--plan {output}" in result["verify_summary_command"]
    assert f"--plan {output}" in result["verify_run_command"]
    assert "--require-plan-match" in result["verify_summary_command"]
    assert "--min-window-count 1" in result["verify_summary_command"]
    assert "--require-window-verifiers" in result["verify_run_command"]
    assert "--require-summary-verify" in result["verify_run_command"]
    assert result["run_metadata"] == {
        "command": "prediction-eval-window-plan",
        "start_label_year": 2025,
        "end_label_year": 2026,
        "train_years": 2,
        "label_years": 1,
        "max_feature_cutoff": "2024-12-31",
        "output_dir": "out/prediction",
        "bill_semantics_root": "out/bill-semantics",
        "congress_archive_manifest": None,
    }
    assert result["output"] == str(output)
    assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()

    written = json.loads(output.read_text(encoding="utf-8"))
    assert written["run_metadata"] == result["run_metadata"]
    assert written["command"] == "prediction-eval-window-plan"
    assert written["window_count"] == 1
    assert written["windows"] == result["windows"]
    assert written["summary_command"] == result["summary_command"]
    assert written["verify_summary_command"] == result["verify_summary_command"]
    assert written["verify_run_command"] == result["verify_run_command"]


