def test_dispatch_prediction_eval_window_summary_aggregates_reports(
    tmp_path: Path,
) -> None:
    report_2025 = tmp_path / "prediction-eval-report-2025.json"
    report_2026 = tmp_path / "prediction-eval-report-2026.json"
    _write_eval_summary_report(
        report_2025,
        training_feature_cutoff=dt.date(2022, 12, 31),
        train_start=dt.date(2023, 1, 1),
        train_end=dt.date(2024, 12, 31),
        feature_cutoff=dt.date(2024, 12, 31),
        label_start=dt.date(2025, 1, 1),
        label_end=dt.date(2025, 12, 31),
        vote_event_id=501,
        vote_date=dt.date(2025, 2, 1),
        vote_option="yea",
    )
    _write_eval_summary_report(
        report_2026,
        training_feature_cutoff=dt.date(2023, 12, 31),
        train_start=dt.date(2024, 1, 1),
        train_end=dt.date(2025, 12, 31),
        feature_cutoff=dt.date(2025, 12, 31),
        label_start=dt.date(2026, 1, 1),
        label_end=dt.date(2026, 12, 31),
        vote_event_id=601,
        vote_date=dt.date(2026, 2, 1),
        vote_option="yea",
    )
    output = tmp_path / "prediction-eval-window-summary.json"

    result = dispatch_command(
        SimpleNamespace(
            command="prediction-eval-window-summary",
            report=[str(report_2026), str(report_2025)],
            require_report_run_metadata=True,
            require_ready_reports=False,
            require_non_overlapping_label_windows=True,
            output=str(output),
        )
    )

    assert result["ok"] is True
    assert result["command"] == "prediction-eval-window-summary"
    assert result["report_count"] == 2
    assert result["window_count"] == 2
    assert result["total_evaluation_label_count"] == 2
    assert [window["label_start"] for window in result["windows"]] == [
        "2025-01-01",
        "2026-01-01",
    ]
    assert result["issue_count"] == 0
    assert result["quality_gate_failure_count"] == 0
    baseline = next(
        model for model in result["models"] if model["model_name"] == "member_vote_rate_baseline"
    )
    assert baseline["label_count"] == 2
    assert baseline["evaluated_count"] == 2
    assert baseline["correct_count"] == 2
    assert baseline["accuracy"] == 1.0
    assert baseline["coverage_rate"] == 1.0
    assert result["output"] == str(output)
    assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
    written = json.loads(output.read_text(encoding="utf-8"))
    assert written["run_metadata"]["command"] == "prediction-eval-window-summary"
    assert written["run_metadata"]["source_state"]["total_evaluation_label_count"] == 2


