    assert result["output_sha256"] == hashlib.sha256(output.read_bytes()).hexdigest()
    written = json.loads(output.read_text(encoding="utf-8"))
    assert written["run_metadata"]["command"] == "verify-prediction-eval-window-summary"
    assert written["run_metadata"]["source_state"]["window_count"] == 2
    assert written["run_metadata"]["source_state"]["windows"] == [
        {
            "path": str(report_2025),
            "training_feature_cutoff": "2022-12-31",
            "train_start": "2023-01-01",
            "train_end": "2024-12-31",
            "feature_cutoff": "2024-12-31",
            "label_start": "2025-01-01",
            "label_end": "2025-12-31",
            "evaluation_label_count": 1,
        },
        {
            "path": str(report_2026),
            "training_feature_cutoff": "2023-12-31",
            "train_start": "2024-01-01",
            "train_end": "2025-12-31",
            "feature_cutoff": "2025-12-31",
            "label_start": "2026-01-01",
            "label_end": "2026-12-31",
            "evaluation_label_count": 1,
        },
    ]


