def _write_eval_summary_report(
    path: Path,
    *,
    training_feature_cutoff: dt.date,
    train_start: dt.date,
    train_end: dt.date,
    feature_cutoff: dt.date,
    label_start: dt.date,
    label_end: dt.date,
    vote_event_id: int,
    vote_date: dt.date,
    vote_option: str,
    include_run_metadata: bool = True,
) -> None:
    report = build_prediction_eval_report(
        training_feature_cutoff=training_feature_cutoff,
        train_start=train_start,
        train_end=train_end,
        feature_cutoff=feature_cutoff,
        label_start=label_start,
        label_end=label_end,
        training_feature_rows=[
            _eval_summary_feature_row("A000001", vote_count=10, yea_count=9),
            _eval_summary_feature_row("B000002", vote_count=10, yea_count=1),
        ],
        evaluation_feature_rows=[
            _eval_summary_feature_row("C000003", vote_count=10, yea_count=9),
        ],
        training_label_rows=[
            _eval_summary_label_row(
                "A000001",
                vote_event_id=vote_event_id - 2,
                vote_date=train_start,
                vote_option="yea",
            ),
            _eval_summary_label_row(
                "B000002",
                vote_event_id=vote_event_id - 1,
                vote_date=train_start,
                vote_option="nay",
            ),
        ],
        evaluation_label_rows=[
            _eval_summary_label_row(
                "C000003",
                vote_event_id=vote_event_id,
                vote_date=vote_date,
                vote_option=vote_option,
            ),
        ],
        ontology_edges=[],
        bill_signal_rows=[],
    )
    payload = report.model_dump(mode="json")
    if include_run_metadata:
        payload["run_metadata"] = {
            "command": "prediction-eval-report",
            "training_feature_cutoff": training_feature_cutoff.isoformat(),
            "train_start": train_start.isoformat(),
            "train_end": train_end.isoformat(),
            "feature_cutoff": feature_cutoff.isoformat(),
            "label_start": label_start.isoformat(),
            "label_end": label_end.isoformat(),
        }
    path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")


def _eval_summary_feature_row(
    bioguide_id: str,
    *,
    vote_count: int,
    yea_count: int,
) -> dict[str, object]:
    return {
        "bioguide_id": bioguide_id,
        "vote_count": vote_count,
        "yea_count": yea_count,
        "nay_count": vote_count - yea_count,
        "present_count": 0,
        "not_voting_count": 0,
        "latest_vote_date": dt.date(2022, 12, 1),
        "vote_event_count": vote_count,
        "party": "D",
        "chamber": "house",
    }


def _eval_summary_label_row(
    bioguide_id: str,
    *,
    vote_event_id: int,
    vote_date: dt.date,
    vote_option: str,
) -> dict[str, object]:
    return {
        "vote_event_id": vote_event_id,
        "chamber": "house",
        "congress": 118 if vote_date.year < 2025 else 119,
        "session_number": 1,
        "roll_call_number": vote_event_id,
        "vote_date": vote_date,
        "question": "On Passage of H.R. 1",
        "result": "Passed",
        "source_url": f"https://clerk.house.gov/Votes/{vote_event_id}",
        "bioguide_id": bioguide_id,
        "member_slug": bioguide_id.lower(),
        "member_name": bioguide_id,
        "party": "D",
        "state": "CA",
        "vote_option": vote_option,
    }
